INSERT INTO Song VALUES(1,'All New Minglewood Blues','all-new-minglewood-blues',unistr('I was born in a desert, raised in a lion''s den\u000aI was born in a desert, raised in a lion''s den\u000aAnd my number one occupation is stealing women from their men\u000a\u000aWell I''m a wanted man in Texas, busted jail and I''m gone for good\u000aYes I''m a wanted man in Texas, busted jail and I''m gone for good\u000aWell the sheriff couldn''t catch me\u000aBut his little girl sure wished she would\u000a\u000aYes and the doctor call me crazy, some says I am some says I ain''t\u000aYes and the doctor call me crazy, some says I am some says I ain’t\u000aThe preacher man call me a sinner, but his little girl call me a saint\u000a\u000aWell a couple of shots of whiskey, women round here start lookin'' good\u000aYes and a couple of shots of whiskey, women round here start lookin'' good\u000aCouple more shots of whiskey, I''m goin'' down to Minglewood\u000a\u000aYes I was born in a desert, raised in a lion''s den\u000aI was born in a desert, raised in a lion''s den\u000aAnd my number one occupation is stealing women from their men\u000aAnd my number one occupation is stealing women from their men\u000a[etc]'),'All New Minglewood Blues Score.pdf',9,NULL,'cover',14,1);
INSERT INTO Song VALUES(2,'Knockin'' on Heaven''s Door','knockin-on-heavens-door',unistr('Mama take this badge from me\u000aI can''t use it anymore\u000aIt''s gettin'' dark, too dark to see\u000aFeels like I''m knockin'' on Heaven''s door\u000a\u000aChorus\u000aKnock knock knockin'' on Heaven''s door\u000aKnock knock knockin'' on Heaven''s door\u000aKnock knock knockin'' on Heaven''s door\u000aKnock knock knockin'' on Heaven''s door\u000a\u000aMama put my guns in the ground\u000aI can''t shoot them anymore\u000aThat cold black cloud is comin'' down\u000aFeels like I''m knockin'' on Heaven''s door\u000a\u000aChorus\u000a\u000aYou just better start sniffin'' your own rank subjugation Jack\u000a''Cause it''s just you against your tattered libido, the bank and the mortician\u000aForever man\u000aAnd it wouldn''t be luck if you could get out of life alive\u000a\u000aChorus\u000a\u000aChorus'),'Knockin'' on Heaven''s Door Score.pdf',NULL,NULL,'cover',21,3);
INSERT INTO Song VALUES(3,'Alabama Getaway','alabama-getaway',unistr('Thirty-two teeth in a jawbone\u000aAlabama''s tryin'' for none\u000aBefore I have to hit him\u000aI hope he''s got the sense to run\u000a\u000aReason the poor girls love him\u000aPromise them everything\u000aWhy they all believe him?\u000aHe wears a big diamond ring\u000a\u000aChorus\u000aAlabama getaway, get away\u000aAlabama getaway, get away\u000aOnly way to please me\u000aJust get down and leave and walk away\u000a\u000aMajordomo Billy Bojangles\u000aSat down and had a drink with me\u000aSaid what about Alabama\u000aThat keeps a-coming back to me?\u000a\u000aI heard your plea in the court house\u000aWitness box began to rock and rise\u000aForty nine sister states\u000aHad Alabama in their eyes\u000a\u000aChorus\u000a\u000aMajor said why don''t we give him\u000aRope enough to hang himself?\u000aNo need to worry the jury\u000aThey''ll probably take care of themselves\u000a\u000aTwenty third psalm Majordomo\u000aReserve me a table for three\u000aDown in the valley of the shadow\u000aJust you, Alabama and me\u000a\u000aChorus'),'Alabama Getaway Score.pdf',1,NULL,NULL,16,3);
INSERT INTO Song VALUES(4,'Me & My Uncle','me-and-my-uncle',unistr('Me and my uncle went ridin'' down\u000aTo South Colorado, West Texas bound\u000aWe stopped over in Santa Fe\u000aThat day on the pony, just about halfway\u000aAnd you know it was the hottest part of the day\u000a\u000aAnd I took the horses up to the stall\u000aWent to the barroom, ordered drinks for all\u000aThree days in the saddle, you know my body hurt\u000aIt being summer, I took off my shirt\u000aAnd I tried to wash off some of that dusty dirt\u000a\u000aWest Texas cowboys, they was all around\u000aWheat, liquor and money, they loaded down\u000aSo soon after payday, no, it seemed a shame\u000aYou know my uncle, he starts playin'' the game\u000aHey now, high-low jack and the winner take the hand\u000a\u000aMy uncle start winning, the cowboys got sore\u000aOne of them called him, and then two more\u000aAccused him of cheatin'', oh no, it couldn''t be\u000aI know my uncle, he''s as honest as me\u000aHey now, I''m as honest as a Denver man can be, that''s right\u000a\u000aOne of them cowboys, he starts to draw\u000aAnd I shot him down, Lord, he never saw\u000aShot me another, hot damn, he won''t grow old\u000aIn the confusion, my uncle grabbed the gold\u000aAnd we hightail it down to Mexico\u000a\u000aNow I love those cowboys, I love their gold\u000aLove my uncle, God rest his soul\u000aTaught me good, Lord, taught me all I know\u000aTaught me so well, that I grabbed that gold\u000aI left his dead ass there by the side of the road, yeah'),'Me & My Uncle Score.pdf',6,NULL,'cover',7,1);
INSERT INTO Song VALUES(5,'Let the Good Times Roll','let-the-good-times-roll',unistr('Chorus\u000aGet in the groove and let the good times roll\u000aWe''re gonna stay here till we soothe our soul\u000aIf it takes all night long\u000aCome on and let the good times roll\u000aWe''re gonna stay here till we soothe our soul\u000aIf it takes all night long\u000a\u000aThe evening sun is sinking low\u000aThe clock on the wall says it''s time to go\u000aI got plans, and I got plans for you\u000aI tell you exactly what we''re all gonna do\u000a\u000aChorus\u000a\u000aIt might be twelve o''clock and it might be three\u000aTime doesn''t mean that much to me\u000aAin''t felt this way since I don''t know when\u000aMight not feel this way again\u000a\u000aChorus\u000a\u000aIt might be six o''clock and it might be eight\u000aIt don''t matter that it''s getting late\u000aWe''re gonna make the band play one more song\u000aGet in the groove if it takes all night long\u000a\u000aChorus\u000a\u000aAll night (all night)\u000aAll night (all night)\u000aIf it takes all night (all night)\u000aYou know it might take all night long (all night)\u000aAll night long (all night)\u000aAll night long (all night)\u000a\u000a[etc]\u000a\u000aGet in the groove and let the good times roll\u000aWe''re gonna stay here till we soothe our soul\u000aIf it takes all night long'),'Good Times Score.pdf',NULL,NULL,'cover',22,NULL);
INSERT INTO Song VALUES(6,'Loser','loser',unistr('If I had a gun for every ace that I had drawn\u000aI could arm a town the size of Abilene\u000aDon''t you push me baby, ''cause I''m moaning low\u000aAnd you know I''m only in it for the gold\u000a\u000aAll that I am asking for is ten gold dollars\u000aAnd I could pay you back with one good hand\u000aYou can look around at the wide world over\u000aBut you''ll never find another honest man\u000a\u000aLast fair deal in the country, sweet Susie\u000aLast fair deal in the town\u000aPut your gold money where your love is baby\u000aBefore you let my deal go down\u000a\u000aDon''t you push me baby, ''cause I''m moaning low\u000aWell I know a little something you won''t ever know\u000aDon''t you touch hard liquor, just a cup of cold coffee\u000aGonna get up in the morning and go\u000a\u000aEverybody''s bragging and drinking that wine\u000aI can tell the Queen of Diamonds by the way she shines\u000aCome to daddy on an inside straight\u000aWell I got no chance of losing this time\u000aWell I got no chance of losing this time'),'Loser Score.pdf',4,NULL,NULL,9,3);
INSERT INTO Song VALUES(7,'Lost Sailor','lost-sailor',unistr('Compass card is spinning\u000aHelm is swingin'' to and fro\u000aOoh where''s the dog star\u000aOoh where''s the moon\u000aYou''re lost sailor\u000aYou''ve been too long at sea\u000a\u000aSome days the gales are howling\u000aSome days the sea is still as glass\u000aOoh reef the mainsail\u000aOoh lash the mast\u000aYou''re lost sailor\u000aYou''ve been too long at sea\u000a\u000aNow the shore-lights beckon\u000aYeah there''s a price for being free\u000a\u000aYeah the sea birds cry\u000aThere''s a ghost wind blowin''\u000aIt''s calling you to that misty swirling sea\u000aTill the chains of your dreams are broken\u000aNo place in this world you can be\u000a\u000aYou''re lost sailor\u000aYou''ve been way too long at sea\u000aNow the shore-lights beckon\u000aYeah there''s a price for being free\u000a\u000aDrifting yeah drifting\u000aYeah drifting and dreaming\u000a\u000a''Cause there''s a place you''ve never been\u000aMaybe a place you''ve never seen\u000aYou can hear her calling on the wind\u000aGo on and drift your life away\u000aYeah just drifting and dreaming\u000aMaybe drift your life away\u000aDrifting and dreaming\u000aYes I''m going on a dream\u000aMaybe going on a dream\u000aMaybe going on a dream\u000aMaybe going on a dream'),'Lost Sailor Score.pdf',5,NULL,NULL,16,1);
INSERT INTO Song VALUES(8,'One More Saturday Night','one-more-saturday-night',unistr('Went down to the mountain, I was drinking some wine\u000aLooked up in the Heaven, Lord, I saw a mighty sign\u000aWritten fire across the heaven, plain as black and white\u000a''Get prepared, there''s gonna be a party tonight''\u000a\u000aChorus\u000aUh uh hey, Saturday night\u000aHey uh uh, one more Saturday night\u000aHey, Saturday night\u000a\u000aNow everybody''s dancin'' down the local armory\u000aWith a basement full of dynamite and live artillery\u000aTemperature keeps risin'', everybody gettin'' high\u000aCome the rockin'' stroke of midnight, the place is gonna fly\u000a\u000aChorus\u000a\u000aTurn on channel six, the President comes on the news\u000aSays, "I get no satisfaction, that''s why I sing the blues"\u000aHis wife say, "Don''t get crazy, Lord, you know just what to do\u000aCrank up that old Victrola, put on your rockin'' shoes"\u000a\u000aChorus\u000a\u000aThen God way up in Heaven, for whatever it was worth\u000aThought He''d have a big old party, thought He''d call it Planet Earth\u000aDon''t worry about tomorrow, Lord, you''ll know it when it comes\u000aWhen the rock and roll music meets the risin'' Planet Sun\u000a\u000aChorus\u000a\u000aHey, another Saturday night\u000aHey, another Saturday night\u000aEverybody''s get high\u000aHey, another Saturday night\u000aOne more Saturday, one more Saturday night'),'One More Saturday Night Score.pdf',3,NULL,NULL,10,1);
INSERT INTO Song VALUES(9,'Saint of Circumstance','saint-of-circumstance',unistr('This must be heaven\u000aLast station on the line\u000aYou must be the angel\u000aI thought I might never find\u000a\u000aWas it you I heard singing\u000aOh when I was chasing dreams\u000a\u000aDriven on the wind\u000aLike the dust that blows around\u000aAnd the rain fallin'' down\u000a\u000aI never know now\u000aJust don''t ever know, no, no\u000a\u000aGot to be heaven\u000a''Cause here''s where the rainbow ends\u000aAnd if this ain''t the real thing\u000aWell it''s close enough to pretend\u000a\u000aWhen that wind blows\u000aAnd the night''s about to fall\u000aI can hear the siren''s call\u000aIt''s a certain sort of sound\u000aAnd the rain fallin'' down\u000aRain fallin'' down\u000aRain falling down now\u000aRain falling down now\u000aRain falling down\u000a\u000aHoles in what''s left of my reason\u000aHoles in the knees of my blues\u000aOdds against me been increasing\u000aBut I''ll pull through\u000a\u000aNever could read no road-map\u000aNo I don''t know what the weather might do\u000aBut hear that witch wind whining\u000aSee that dog star shining\u000aI got a feelin'' there''s no time to lose\u000aNo time to lose\u000a\u000aI never know, no, no\u000aJust don''t ever know\u000aNever know, no\u000a\u000aWell it''s been heaven\u000aBut even rainbows will end\u000aNow my sails are filling\u000aThe wind is willing\u000aAnd I''m good as gone again\u000aI''m still walkin''\u000aSo I''m sure that I can dance\u000aJust a saint of circumstance\u000aJust a tiger in a trance\u000aAnd the rain fallin'' down\u000aRain falling down\u000aRain falling down\u000aRain falling down\u000aRain falling down\u000a\u000aWell I never know now\u000aJust don''t ever know, no, no\u000aSure don''t know what I''m goin'' for\u000aBut I''m gonna go for it for sure\u000aSure don''t know what I''m goin'' for\u000aBut I''m gonna go for it for sure\u000aListen\u000aSure don''t know what I''m goin'' for\u000aBut I''m gonna go for it for sure\u000aHey\u000aSure don''t know what I''m goin'' for\u000aMaybe just going on a dream now\u000aBut I''m gonna go for it for sure\u000aHey, ya\u000aSure don''t know what I''m goin'' for\u000aWell I just don''t know, [and I''m the same]\u000aBut I''m gonna go for it for sure\u000aI just go for it for sure now\u000aListen\u000aSure don''t know what I''m goin'' for\u000aMake [?], that''s what I say now\u000aBut I''m gonna go for it for sure\u000aGotta go, go, go for sure\u000aSure don''t know what I''m goin'' for\u000a[falsetto] Maybe going on a dream now\u000aBut I''m gonna go for it for sure\u000a[falsetto] Maybe going on a dream, dream'),'Saint of Circumstance Score.pdf',6,NULL,NULL,16,1);
INSERT INTO Song VALUES(10,'Peggy-O','peggy-o',unistr('As we rode out to Fennario\u000aAs we rode out to Fennario\u000aOur captain fell in love with a lady like a dove\u000aAnd he called her by name pretty Peggy-O\u000a\u000aWill you marry me, pretty Peggy-O\u000aWill you marry me, pretty Peggy-O\u000aIf you will marry me, I will set your cities free\u000aAnd free all the ladies in the area-O\u000a\u000aI would marry you, sweet William-O\u000aI would marry you, sweet William-O\u000aI would marry you, but your guineas are too few\u000aAnd I fear my mama would be angry-O\u000a\u000aWhat would your mama think, pretty Peggy-O\u000aWhat would your mama think, pretty Peggy-O\u000aWhat would your mama think if she heard my guineas clink\u000aAnd saw me marching at the head of my soldiers-O\u000a\u000aIf ever I return, pretty Peggy-O\u000aIf ever I return, pretty Peggy-O\u000aIf ever I return, all your cities I will burn\u000aDestroy all the ladies in the area-O\u000a\u000aCome stepping down the stairs, pretty Peggy-O\u000aCome stepping down the stairs, pretty Peggy-O\u000aCome stepping down the stairs, combing back your yellow hair\u000aAnd bid a last farewell to young William-O\u000a\u000aSweet William he is dead, pretty Peggy-O\u000aSweet William he is dead, pretty Peggy-O\u000aSweet William he is dead, and he died for a maid\u000aAnd he''s buried in the Louisiana country-O\u000a\u000aAs we rode out to Fennario\u000aAs we rode out to Fennario\u000aOur captain fell in love with a lady like a dove\u000aAnd he called her by name pretty Peggy-O'),'Peggy-O Score.pdf',NULL,NULL,'cover',23,3);
INSERT INTO Song VALUES(11,'Shakedown Street','shakedown-street',unistr('You tell me this town ain''t got no heart\u000a(Well, well, well, you can never tell)\u000aThe sunny side of the street is dark\u000a(Well, well, well, you can never tell)\u000aMaybe that''s ''cause it''s midnight (note 1\u000aAnd the dark of the moon besides\u000aMaybe the dark is from your eyes\u000a(Maybe the dark is from your eyes)\u000aMaybe the dark is from your eyes\u000a(Maybe the dark is from your eyes)\u000aMaybe the dark is from your eyes\u000a(Maybe the dark is from your eyes)\u000aYou know you got such dark eyes\u000a\u000aChorus\u000aNothing shaking on Shakedown Street\u000aUsed to be the heart of town\u000aDon''t tell me this town ain''t got no heart\u000aYou just got to poke around\u000a\u000aYou think you''ve seen this town clear through\u000a(Well, well, well, you can never tell)\u000aNothing here could interest you\u000a(Well, well, well, you can never tell)\u000aIt''s not because you missed out\u000aOn the thing that we had to start\u000aMaybe you had too much too fast\u000a(Maybe you had too much too fast)\u000aMaybe you had too much too fast\u000a(Maybe you had too much too fast)\u000aMaybe you had too much too fast\u000a(Maybe you had too much too fast)\u000aAnd just overplayed your part\u000a\u000aChorus\u000a\u000aSince I''m passing your way today\u000a(Well, well, well, you can never tell)\u000aI just stopped in ''cause I want to say\u000a(Well, well, well, you can never tell)\u000aI recall your darkness\u000aWhen it crackled like a thunder cloud\u000aDon''t tell me this town ain''t got no heart\u000a(Don''t tell me this town ain''t got no heart)\u000aDon''t tell me this town ain''t got no heart\u000a(Don''t tell me this town ain''t got no heart)\u000aDon''t tell me this town ain''t got no heart\u000a(Don''t tell me this town ain''t got no heart)\u000aI can hear it beat out loud\u000a\u000aChorus'),'Shakedown Street Score.pdf',3,NULL,NULL,14,3);
INSERT INTO Song VALUES(12,'Ramble on Rose','ramble-on-rose',unistr('Just like Jack the Ripper\u000aJust like Mojo Hand\u000aJust like Billy Sunday\u000aIn a shotgun rag-time band\u000a\u000aJust like New York City\u000aJust like Jericho\u000aPace the halls and climb the walls\u000aAnd get out when they blow\u000a\u000aChorus\u000aDid you say your name was Rambling Rose?\u000aRamble on baby, settle down easy\u000aRamble on Rose\u000a\u000aJust like Jack and Jill\u000aMama told the sailor\u000aOne heat up and one cool down\u000aLeave nothing for the tailor\u000a\u000aJust like Jack and Jill\u000aPapa told the jailer\u000aOne go up and one come down\u000aDo yourself a favour\u000a\u000aChorus\u000a\u000aBridge\u000aI''m gonna sing you\u000aA hundred verses in ragtime\u000aI know this song\u000aIt ain''t never gonna end\u000aI''m gonna march you up and down\u000aThe local county line\u000aTake you to the leader\u000aOf the band\u000a\u000aJust like Crazy Otto\u000aJust like Wolfman Jack\u000aSitting plush with a royal flush\u000aAces back to back\u000a\u000aJust like Mary Shelley\u000aJust like Frankenstein\u000aClank your chains and count your change\u000aAnd try to walk the line\u000a\u000aChorus\u000a[bridge]\u000a\u000aGoodbye Mama and Papa\u000aGoodbye Jack and Jill\u000aThe grass ain''t greener, the wine ain''t sweeter\u000aEither side of the hill\u000a\u000aChorus\u000a\u000aRamble on Rose'),'Ramble on Rose Score.pdf',10,NULL,NULL,10,3);
INSERT INTO Song VALUES(13,'The Music Never Stopped','the-music-never-stopped',unistr('There''s mosquitoes on the river\u000aFish are rising up like birds\u000aIt''s been hot for seven weeks now\u000aToo hot to even speak now\u000aDid you hear what I just heard?\u000a\u000aSay, it might have been a fiddle\u000aOr it could have been the wind\u000aBut there seems to be a beat now\u000aI can feel it in my feet now\u000aListen here it comes again\u000a\u000aThere''s a band out on the highway\u000aThey''re high-stepping into town\u000aIt''s a rainbow full of sound\u000aIt''s fireworks, calliopes and clowns\u000aEverybody''s dancing\u000a\u000aCome on children, come on children\u000aCome on clap your hands\u000a\u000aSun went down in honey\u000aAnd the moon came up in wine\u000aYou know stars were spinning dizzy\u000aLord the band kept us so busy\u000aWe forgot about the time\u000a\u000aThey''re a band beyond description\u000aLike Jehovah''s favourite choir\u000aPeople joining hand in hand\u000aWhile the music plays the band\u000aLord they''re setting us on fire\u000a\u000aCrazy rooster crowing midnight\u000aBalls of lightning roll along\u000aOld men sing about their dreams\u000aWomen laugh and children scream\u000aAnd the band keeps playing on\u000a\u000aKeep on dancing through to daylight\u000aGreet the morning air with song\u000aNo one''s noticed but the band''s all packed and gone\u000aWas it ever here at all?\u000aBut they kept on dancing\u000a\u000aCome on children, come on children\u000aCome on clap your hands\u000a\u000aWell the cool breeze came on Tuesday\u000aAnd the corn''s a bumper crop\u000aAnd the fields are full of dancing\u000aFull of singing and romancing\u000aThe music never stopped'),'The Music Never Stopped Score.pdf',4,NULL,NULL,13,NULL);
INSERT INTO Song VALUES(14,'Mississippi Half-Step Uptown Toodeloo','mississippi-half-step-uptown-toodeloo',unistr('On the day that I was born Daddy sat down and cried\u000aI had the mark just as plain as day, I could not be denied\u000aThey say that Cain caught Abel rolling loaded dice\u000aAce of spades behind his ear and him not thinking twice\u000a\u000aChorus\u000aHalf step, Mississippi uptown toodleloo\u000aHello baby I''m gone goodbye\u000aHalf a cup of rock and rye\u000aFarewell to you old southern skies\u000aI''m on my way, on my way\u000a\u000aIf all you got to live for is what you left behind\u000aGet yourself a powder charge and seal that silver mine\u000aLost my boots in transit babe, pile of smoking leather\u000aNailed a retread to my feet and prayed for better weather\u000a\u000aChorus\u000a\u000aThey say that when your ship comes in, first man takes the sails\u000aSecond takes the after deck, third the planks and rails\u000aWhat''s the point of calling shots, this cue ain''t straight in line\u000aCue ball''s made of styrofoam and no-one''s got the time\u000a\u000aChorus\u000a\u000aAcross the Rio Grand-eo\u000aAcross the lazy river\u000a[etc]'),'Mississippi Half-Step Uptown Toodeloo Score.pdf',1,NULL,NULL,11,3);
INSERT INTO Song VALUES(15,'Stella Blue','stella-blue',unistr('All the years combine\u000aThey melt into a dream\u000aA broken angel sings\u000aFrom a guitar\u000a\u000aIn the end there''s just a song\u000aComes crying up the night\u000aThrough all the broken dreams\u000aAnd vanished years\u000a\u000aStella Blue\u000aStella Blue\u000a\u000aWhen all the cards are down\u000aThere''s nothing left to see\u000aThere''s just the pavement left\u000aAnd broken dreams\u000a\u000aIn the end there''s still that song\u000aComes crying like the wind\u000aDown every lonely street\u000aThat''s ever been\u000a\u000aStella Blue\u000aStella Blue\u000a\u000aI''ve stayed in every blue light cheap hotel\u000aCan''t win for trying\u000aDust off those rusty strings just one more time\u000aGonna make them shine\u000a\u000aIt all rolls into one\u000aAnd nothing comes for free\u000aThere''s nothing you can hold\u000aFor very long\u000a\u000aAnd when you hear that song\u000aCome crying like the wind\u000aIt seems like all this life\u000aWas just a dream\u000a\u000aStella Blue\u000aStella Blue'),'Stella Blue Score.pdf',4,NULL,NULL,11,3);
INSERT INTO Song VALUES(16,'The Other One','the-other-one',unistr('Spanish lady comes to me, she lays on me this roes.\u000aIt rainbow spirals round and round it trembles and explodes.\u000aIt left a smoking crater of my mind I like to blow away.\u000aBut the heat came ''round and busted me for smiling on a cloudy day.\u000a\u000aChorus\u000aComin'', comin'', comin'' around, comin'', around,\u000acomin'', around, in a circle\u000aComin'', comin'', comin'' around, comin'' around, in a circle,\u000aComin'', comin'', comin'' around, comin'' in a circle.\u000a\u000aSkippin'' through the lily fields I came across an empty space,\u000aIt trembled and exploded, left a bus stop in it''s place.\u000aThe bus came by and I got on, that''s when it all began,\u000aThere was cowboy Neal at the wheel of the bus to never ever land.\u000a\u000aChorus'),'The Other One Score.pdf',1,NULL,NULL,2,1);
INSERT INTO Song VALUES(17,'Tennessee Jed','tennessee-jed',unistr('Cold iron shackles, ball and chain\u000aListen to the whistle of the evening train\u000aYou know you bound to wind up dead\u000aIf you don''t head back to Tennessee Jed\u000a\u000aRich man step on my poor head\u000aWhen you get back you better butter my bread\u000aWell you know it''s like I said\u000aYou better head back to Tennessee Jed\u000a\u000aChorus\u000aTennessee, Tennessee\u000aThere ain''t no place I''d rather be\u000aBaby won''t you carry me\u000aBack to Tennessee\u000a\u000aDrink all day and rock all night\u000aThe law come to get you if you don''t walk right\u000aGot a letter this morning, baby, and all it read\u000aYou better head back to Tennessee Jed\u000a\u000aI dropped four flights and cracked my spine\u000aBuddy come quick with the iodine\u000aCatch a few winks, baby, under the bed\u000aThen you head back to Tennessee Jed\u000a\u000aChorus\u000a\u000aI ran into Charlie Phogg\u000aBlacked my eye and he kicked my dog\u000aMy doggie turned to me and he said\u000aLet''s head back to Tennessee Jed\u000a\u000aI woke up feeling mean\u000aI went down to play the slot machine\u000aThe wheels turned around and the letters read\u000aYou better head back to Tennessee Jed\u000a\u000aChorus'),'Tennessee Jed Score.pdf',13,NULL,NULL,10,3);
INSERT INTO Song VALUES(18,'Ship of Fools','ship-of-fools',unistr('Went to see the captain, strangest I could find\u000aLaid my proposition down, laid it on the line\u000aI won''t slave for beggar''s pay, likewise gold and jewels\u000aBut I would slave to learn the way to sink your ship of fools\u000a\u000aChorus\u000aShip of fools on a cruel sea\u000aShip of fools sail away from me\u000aIt was later than I thought when I first believed you\u000aBut now I cannot share your laughter, ship of fools\u000a\u000aSaw your first ship sink and drown from rocking of the boat\u000aAnd all that could not sink or swim was just left there to float\u000aI won''t leave you drifting down but whoa it makes me wild\u000aWith thirty years upon my head to have you call me child\u000a\u000aChorus\u000a\u000aThe bottles stand as empty now, as they were filled before\u000aTime there was and plenty, but from that cup no more\u000aThough I could not caution all, I still might warn a few\u000aDon''t lend your hand to raise no flag atop no ship of fools\u000a\u000aChorus'),'Ship of Fools Score.pdf',8,NULL,NULL,12,3);
INSERT INTO Song VALUES(19,'Touch of Grey','touch-of-grey',unistr('It must be getting early\u000aClocks are running late\u000aPaint by numbers morning sky\u000aLooks so phony\u000a\u000aDawn is breaking everywhere\u000aLight a candle, curse the glare\u000aDraw the curtains, I don''t care\u000a''Cause it''s alright\u000a\u000aI will get by\u000aI will get by\u000aI will get by\u000aI will survive\u000a\u000aI see you got your list out\u000aSay your piece and get out\u000aYes I got the gist of it\u000aBut it''s alright\u000a\u000aSorry that you feel that way\u000aThe only thing there is to say\u000aEvery silver lining''s got a\u000aTouch of grey\u000a\u000aIt''s a lesson to me\u000aThe Ables and the Bakers and the C''s\u000aThe A B C''s\u000aWe all must face\u000aAnd try to keep a little grace\u000a\u000aI know the rent is in arrears\u000aThe dog has not been fed in years\u000aIt''s even worse than it appears\u000aBut it''s alright\u000a\u000aCows are giving kerosene\u000aThe kid can''t read at seventeen\u000aThe words he knows are all obscene\u000aBut it''s alright\u000a\u000aI will get by\u000aI will get by\u000aI will get by\u000aI will survive\u000a\u000aIt''s a lesson to me\u000aThe Deltas and the East and the Freeze\u000aThe A B C''s\u000aWe all think of\u000aAnd try to keep a little love\u000a\u000aThe shoe is on the hand it fits\u000aThere''s really nothing much to it\u000aWhistle through your teeth and spit\u000a''Cause it''s alright\u000a\u000aOh well a touch of grey\u000aKind of suits you anyway\u000aThat was all I had to say\u000aAnd it''s alright\u000a\u000aI will get by\u000aI will get by\u000aI will get by\u000aI will survive\u000a\u000aWe will get by\u000aWe will get by\u000aWe will get by\u000aWe will survive'),'Touch of Grey Score.pdf',1,NULL,NULL,17,3);
INSERT INTO Song VALUES(20,'Scarlet Begonias','scarlet-begonias',unistr('As I was walking round Grosvenor Square\u000aNot a chill to the winter but a nip to the air\u000aFrom the other direction she was calling my eye\u000aIt could be an illusion, but I might as well try\u000aMight as well try\u000a\u000aShe had rings on her fingers and bells on her shoes\u000aAnd I knew without asking she was into the blues\u000aShe wore scarlet begonias, tucked into her curls\u000aI knew right away she was not like other girls\u000aOther girls\u000a\u000aIn the thick of the evening when the dealing got rough\u000aShe was too pat to open and too cool to bluff\u000aAs I picked up my matches and was closing the door\u000aI had one of those flashes I had been there before\u000aBeen there before\u000a\u000aWell I ain''t often right but I''ve never been wrong\u000aIt seldom turns out the way it does in the song\u000aOnce in a while you get shown the light\u000aIn the strangest of places if you look at it right\u000a\u000aWell there ain''t nothing wrong with the way she moves\u000aScarlet begonias or a touch of the blues\u000aAnd there''s nothing wrong with the look that''s in her eyes\u000aI had to learn the hard way to let her pass by\u000aLet her pass by\u000a\u000aThe wind in the willows playing Tea for Two\u000aThe sky was yellow and the sun was blue\u000aStrangers stopping strangers just to shake their hand\u000aEverybody is playing in the heart of gold band\u000aHeart of gold band'),'Scarlet Begonias Score.pdf',5,NULL,NULL,12,3);
INSERT INTO Song VALUES(21,'Terrapin Station','terrapin-station',unistr('Inspiration, move me brightly\u000aLight the song with sense and color\u000aHold away despair\u000aMore than this I will not ask\u000aFaced with mysteries dark and vast\u000aStatements just seem vain at last\u000aSome rise, some fall, some climb\u000aTo get to Terrapin\u000a\u000aCounting stars by candlelight\u000aAll are dim but one is bright\u000aThe spiral light of Venus\u000aRising first and shining best\u000aOh, from the north-west corner\u000aOf a brand new crescent moon\u000aCrickets and cicadas sing\u000aA rare and different tune\u000aTerrapin Station\u000aIn the shadow of the moon\u000aTerrapin Station\u000aAnd I know we''ll be there soon\u000a\u000a(Terrapin)\u000aI can''t figure out\u000a(Terrapin)\u000aIf it''s the end or beginning\u000a(Terrapin)\u000aBut the train''s put it brakes on\u000a(Terrapin)\u000aAnd the whistle is screaming\u000aTerrapin'),'Terrapin Station Score.pdf',6,NULL,NULL,15,3);
INSERT INTO Song VALUES(22,'U.S. Blues','us-blues',unistr('Red and white, blue suede shoes\u000aI''m Uncle Sam, how do you do\u000aGimme five, still alive\u000aAin''t no luck, I learned to duck\u000a\u000aCheck my pulse, it don''t change\u000aStay seventy two, come shine or rain\u000aWave the flag, pop the bag\u000aRock the boat, skin the goat\u000a\u000aChorus\u000aWave that flag, wave it wide and high\u000aSummertime done come and gone, my oh my\u000a\u000aI''m Uncle Sam, that''s who I am\u000aBeen hiding out, in a rock and roll band\u000aShake the hand that shook the hand\u000aOf P. T. Barnum and Charlie Chan\u000a\u000aShine your shoes, light your fuse\u000aCan you use them old U.S. Blues\u000aI''ll drink your health, share your wealth\u000aRun your life, steal your wife\u000a\u000aChorus\u000a\u000aBack to back, chicken shack\u000aSon of a gun, better change your act\u000aWe''re all confused, what''s to lose\u000aYou can call this song the United States Blues\u000a\u000aChorus'),'U.S. Blues Score.pdf',1,NULL,NULL,12,3);
INSERT INTO Song VALUES(23,'Viola Lee Blues','viola-lee-blues',unistr('The judge decreed it, the clerk he wrote it.\u000aClerk he wrote it down indeed-e\u000aJudge decreed it, clerk he wrote it down\u000aGive you this jail sentence you''ll be Nashville bound\u000a\u000aSome got six month some got one solid.\u000aSome got one solid year indeed-e\u000aSome got six month some got one solid.\u000aBut me and my buddies all got lifetime here\u000a\u000aI wrote a letter I mailed in the air, Mailed it on the air indeed-e\u000aI wrote a letter I mailed in the air.\u000aYou may know by that I''ve got a friend somewhere'),'Viola Lee Blues Score.pdf',9,NULL,'cover',1,5);
INSERT INTO Song VALUES(24,'Wharf Rat','wharf-rat',unistr('Old man down\u000aWay down, down by the docks of the city\u000aBlind and dirty\u000aAsked me for a dime, a dime for a cup of coffee\u000aI got no dime, but I got some time to hear his story\u000a\u000aMy name is August West\u000aAnd I love my Pearly Baker best, more than my wine\u000aMore than my wine\u000aMore than my maker, though he''s no friend of mine\u000a\u000aEveryone said\u000aI''d come to no good\u000aI knew I would\u000aPearly, believed them\u000aHalf of my life\u000aSpent doing time for some other fucker''s crime\u000aThe other half found me\u000aStumbling around, drunk on burgundy wine\u000a\u000aBut I''ll get back on my feet someday\u000aThe good lord willing, if he says I may\u000aI know that the life I''m living''s no good\u000aI''ll get a new start, live the life I should\u000aI''ll get up and fly away\u000aI''ll get up and fly away\u000a\u000aPearly''s been true\u000aTrue to me, true to my dying day, he said\u000aI said to him\u000aI said to him, I''m sure she''s been\u000aI said to him, I''m sure she''s been true to you\u000a\u000aI got up and wandered\u000aWandered downtown, nowhere to go but just to hang around\u000aI''ve got a girl\u000aNamed Bonny Lee, I know that girl''s been true to me\u000aI know she''s been, I''m sure she''s been true to me'),'Wharf Rat Score.pdf',10,NULL,NULL,7,3);
INSERT INTO Song VALUES(25,'Fire on the Mountain','fire-on-the-mountain',unistr('Long distance runner, what you standing there for?\u000aGet up, get off, get out of the door\u000aYou''re playing cold music on the bar room floor\u000aDrowned in your laughter and dead to the core\u000a\u000aThere''s a dragon with matches that''s loose on the town\u000aTake a whole pail of water just to cool him down\u000a\u000aChorus\u000aFire, fire on the mountain\u000aFire, fire on the mountain\u000aFire, fire on the mountain\u000aFire, fire on the mountain\u000a\u000aAlmost ablaze, still you don''t feel the heat\u000aIt takes all you got just to stay on the beat\u000aYou say it''s a living, we all gotta eat\u000aBut you''re here alone, there''s no one to compete\u000aIf mercy''s in business, I wish it for you\u000aMore than just ashes when your dreams come true\u000a\u000aChorus\u000a\u000aBaby''s in scarlet, her shackles in gray\u000aIf loves to love she''s got it salted away\u000aOut of the rat trap and under the wire\u000aOut of the frying pan and into the fire\u000aPut it down heavy, strip it down lean\u000aGot to lay it down dirty and play it back clean\u000a\u000aChorus\u000a\u000aFireman, fireman, call off your dog\u000aThis isn''t a blaze, it''s just a hog in the log\u000aCut up in sections, squirming alive\u000aLost to the world on that fifty-cent jive\u000aThere''s a fire on the mountain, running around\u000aWhat doesn''t go up can never come down\u000a\u000aChorus\u000a\u000aLong distance runner, what you holding out for\u000aCaught in slow motion in a dash to the door\u000aThe flame from your stage has now spread to the floor\u000aYou gave all you had, why you want to give more?\u000aThe more that you give, the more it will take\u000aTo the thin line beyond which you really can''t fake\u000a\u000aChorus'),'Fire on the Mountain Score.pdf',5,NULL,NULL,14,3);
INSERT INTO Song VALUES(26,'He''s Gone','hes-gone',unistr('Rat in a drain ditch, caught on a limb\u000aYou know better, but I know him\u000a\u000aLike I told you, what I said\u000aSteal your face right off your head\u000a\u000aChorus\u000aAnd now he''s gone\u000aNow he''s gone, Lord he''s gone\u000aHe''s gone\u000aLike a steam locomotive rolling down the track\u000aHe''s gone, gone, and nothing''s gonna bring him back\u000aHe''s gone\u000a\u000aNine mile skid on a ten mile ride\u000aHot as a pistol but cool inside\u000a\u000aCat on a tin roof, dogs in a pile\u000aNothing left to do but smile, smile, smile\u000a\u000aChorus\u000a\u000aGoing where the wind don''t blow so strange\u000aMaybe off on some high cold mountain range\u000aLost one round but the price wasn''t anything\u000aA knife in the back and more of the same\u000a\u000aSame old\u000aRat in a drain ditch, caught on a limb\u000aYou know better, but I know him\u000a\u000aLike I told you, like I said\u000aSteal your face right off your head\u000a\u000aChorus\u000a\u000aOoh, nothing''s gonna bring him back\u000aOoh, nothing''s gonna bring him back\u000aOoh, nothing''s gonna bring him back\u000a[etc]'),'He''s Gone Score.pdf',2,NULL,NULL,10,3);
INSERT INTO Song VALUES(27,'Looks Like Rain','looks-like-rain',unistr('I woke today, and felt your side of bed\u000aThe covers were still warm where you''d been layin''\u000aYou were gone, my heart was filled with dread\u000aYou might not be sleeping here again\u000a\u000aIt''s all right, ''cause I love you\u000aAnd that''s not gonna change\u000aRun me round, make me hurt again and again\u000aBut I''ll still sing you love songs\u000aWritten in the letters of your name\u000aAnd brave the storm to come\u000aFor it surely looks like rain\u000a\u000aDid you ever waken to the sound of street cats making love\u000aAnd guess from their cries you were listening to a fight\u000aWell you know, hate''s just the last thing they''re thinking of\u000aThey''re only trying to make it through the night\u000a\u000aI only want to hold you, I don''t want to tie you down\u000aOr fence you in the lines I might have drawn\u000aIt''s just that I have gotten used to having you around\u000aMy landscape would be empty if you were gone\u000a\u000aIt''s all right, ''cause I love you\u000aAnd that''s not gonna change\u000aRun me round, make me hurt again and again\u000aBut I''ll still sing you love songs\u000aWritten in the letters of your name\u000aAnd brave the storm to come\u000aFor it surely looks like rain'),'Looks Like Rain Score.pdf',5,NULL,NULL,8,1);
INSERT INTO Song VALUES(28,'Loose Lucy','loose-lucy',unistr('Loose Lucy is my delight\u000aShe comes running and we ball all night\u000aRound and round and round and round\u000aDon''t take much to get me on the ground\u000aShe''s my yo-yo, I''m her string\u000aListen to the birds on the hot wire sing\u000a\u000aChorus\u000aSinging yeah, yeah, yeah, yeah\u000aSinging thank you, for a real good time\u000a\u000aI got jumped coming home last night\u000aShadow in the alley turned out all my lights\u000aRound and round and round and round\u000aDon''t take much to get me on the ground\u000aLoose Lucy, she was sore\u000aSays I know you can''t want my love no more,\u000a\u000aChorus\u000a\u000aBebop baby, how can this be\u000aI know you''ve been out a cheating on me\u000aRound and round and round and round\u000aDon''t take much to get the word around\u000aCross my heart and hope to die\u000aI was just hanging out with the other guys\u000a\u000aChorus\u000a\u000aWent back home with two black eyes\u000aYou know I''ll love her till the day I die\u000aRound and round and round and round\u000aDon''t take much to get the word around\u000aI like your smile but I ain''t your type\u000aDon''t shake the tree when the fruit ain''t ripe\u000a\u000aChorus'),'Loose Lucy Score.pdf',4,NULL,NULL,12,3);
INSERT INTO Song VALUES(29,'Goin'' Down the Road Feeling Bad','goin-down-the-road-feeling-bad',unistr('Chorus\u000aGoing down the road feeling bad\u000aGoing down the road feeling bad\u000aGoing down the road feeling bad, hey hey hey, yeah\u000aDon''t wanna be treated this a way\u000a\u000aGoing where the climate suits my clothes\u000aI''m going where the climate suits my clothes\u000aGoing where the climate suits my clothes\u000aDon''t wanna be treated this a way\u000a\u000aChorus\u000a\u000aGoing where the water tastes like wine\u000aWell I''m going where the water tastes like wine\u000aGoing where the water tastes like wine\u000aI don''t wanna be treated this a way\u000a\u000aChorus'),'Goin'' Down the Road Feeling Bad Score.pdf',11,NULL,'cover',7,3);
INSERT INTO Song VALUES(30,'Uncle John''s Band','uncle-johns-band',unistr('Well the first days are the hardest days, don''t you worry any more\u000a''Cause when life looks like easy street, there is danger at your door\u000aThink this through with me, let me know your mind\u000aWo-oh, what I want to know is, are you kind?\u000a\u000aIt''s a buck dancer''s choice my friend, better take my advice\u000aYou know all the rules by now, and the fire from the ice\u000aWill you come with me, won''t you come with me?\u000aWo-oh, what I want to know, will you come with me?\u000a\u000aGod damn, well I declare, have you seen the like?\u000aTheir walls are built of cannon balls\u000aTheir motto is "don''t" tread on me"\u000a\u000aCome hear Uncle John''s Band, playing to the tide\u000aCome with me or go alone\u000aHe''s come to take his children home\u000a\u000aIt''s the same story the crow told me, it''s the only one he knows\u000aLike the morning sun you come and like the wind you go\u000aAin''t no time to hate, barely time to wait\u000aWo-oh, what I want to know, where does the time go?\u000a\u000aI live in a silver mine and I call it beggar''s tomb\u000aI got me a violin and I beg you call the tune\u000aAnybody''s choice, I can hear your voice\u000aWo-oh, what I want to know, how does the song go?\u000a\u000aCome hear Uncle John''s Band, by the river side\u000aGot some things to talk about\u000aHere beside the rising tide\u000a\u000aCome hear Uncle John''s Band, playing to the tide\u000aCome with me or go alone\u000aHe''s come to take his children home\u000a\u000aWo-oh what I want to know, how does the song go?\u000a\u000aCome hear Uncle John''s Band, by the river side\u000aGot some things to talk about\u000aHere beside the rising tide'),'Uncle John''s Band Score.pdf',1,NULL,NULL,5,NULL);
INSERT INTO Song VALUES(31,'New Speedway Boogie','new-speedway-boogie',unistr('Please don''t dominate the rap, Jack\u000aIf you got nothing new to say\u000aIf you please, don''t back up the track\u000aThis train''s got to run today\u000a\u000aI spent a little time in the mountain\u000aSpent a little time on the hill\u000aI heard some say "better run away"\u000aOthers say "better stand still"\u000a\u000aNow I don''t know but I''ve been told\u000aIt''s hard to run with the weight of gold\u000aOther hand I heard it said\u000aIt''s just as hard with the weight of lead\u000a\u000aWho can deny? Who can deny?\u000aIt''s not just a change in style\u000aOne step done and another begun\u000aIn I wonder how many miles?\u000a\u000aI spent a little time on the mountain\u000aSpent a little time on the hill\u000aThings went down we don''t understand\u000aBut I think in time we will\u000a\u000aNow I don''t know but I was told\u000aIn the heat of the sun a man died of cold\u000aDo we keep on coming or stand and wait\u000aWith the sun so dark and the hour so late?\u000a\u000aYou can''t overlook the lack Jack\u000aOf any other highway to ride\u000aIt''s got no signs or dividing lines\u000aAnd very few rules to guide\u000a\u000aI spent a little time on the mountain\u000aSpent a little time on the hill\u000aI saw things getting out of hand\u000aI guess they always will\u000a\u000aNow, I don''t know but I''ve been told\u000aIf the horse don''t pull, you got to carry the load\u000aI don''t know whose back''s that strong\u000aMaybe find out before too long\u000a\u000aOne way or another\u000aOne way or another\u000aOne way or another\u000aThis darkness got to give\u000a[etc]'),'New Speedway Boogie Score.pdf',4,NULL,NULL,5,3);
INSERT INTO Song VALUES(32,'Ripple','ripple',unistr('If my words did glow with the gold of sunshine\u000aAnd my tunes were played on the harp unstrung\u000aWould you hear my voice come through the music?\u000aWould you hold it near, as it were your own?\u000a\u000aIt''s a hand-me-down, the thoughts are broken\u000aPerhaps they''re better left unsung\u000aI don''t know, don''t really care\u000aLet there be songs to fill the air\u000a\u000aRipple in still water\u000aWhen there is no pebble tossed\u000aNor wind to blow\u000a\u000aReach out your hand if your cup be empty\u000aIf your cup is full may it be again\u000aLet it be known there is a fountain\u000aThat was not made by the hands of man\u000a\u000aThere is a road, no simple highway\u000aBetween the dawn and the dark of night\u000aAnd if you go, no one may follow\u000aThat path is for your steps alone\u000a\u000aRipple in still water\u000aWhen there is no pebble tossed\u000aNor wind to blow\u000a\u000aYou who choose to lead must follow\u000aBut if you fall, you fall alone\u000aIf you should stand, then who''s to guide you?\u000aIf I knew the way, I would take you home'),'Ripple Score.pdf',6,NULL,NULL,6,3);
INSERT INTO Song VALUES(33,'Here Comes Sunshine','here-comes-sunshine',unistr('Wake of the flood, laughing water, forty nine\u000aGet out the pans, don''t just stand there dreaming, get out the way\u000aGet out the way\u000a\u000aChorus\u000aHere comes sunshine\u000aHere comes sunshine\u000a\u000aLine up a long shot, maybe try it two times, maybe more\u000aGood to know you got shoes to wear, when you find the floor\u000aWhy hold out for more\u000a\u000aChorus\u000a\u000aAsking you nice now, keep the mother rolling, one more time\u000aBeen down before, you just don''t have to go no more\u000aNo more\u000a\u000aChorus'),'Here Comes Sunshine Score.pdf',5,NULL,NULL,11,3);
INSERT INTO Song VALUES(34,'Row Jimmy','row-jimmy',unistr('Julie catch a rabbit by his hair\u000aCome back step, like to walk on air\u000aGet back home where you belong\u000aAnd don''t you run off no more\u000a\u000aDon''t hang your head, let the two-time roll\u000aGrass shack nailed to a pine wood floor\u000aAsk the time baby I don''t know\u000aCome back later, gonna let it show\u000a\u000aChorus\u000aAnd I say row, Jimmy, row\u000aGonna get there, I don''t know\u000aSeems a common way to go\u000aGet down and row, row, row, row, row\u000a\u000aHere''s a half a dollar if you dare\u000aDouble twist when you hit the air\u000aLook at Julie down below\u000aThe levee doing the dopaso\u000a\u000aChorus\u000a\u000aBroken heart don''t feel so bad\u000aYou ain''t got half of what you thought you had\u000aRock your baby to and fro\u000aNot too fast and not too slow\u000a\u000aChorus\u000a\u000aThat''s the way it''s been in town\u000aEver since they tore the juke box down\u000aTwo bit piece don''t buy no more\u000aNot so much as it done before\u000a\u000aChorus'),'Row Jimmy Score.pdf',3,NULL,NULL,11,3);
INSERT INTO Song VALUES(35,'Standing on the Moon','standing-on-the-moon',unistr('Standing on the moon, I got no cobweb on my shoe\u000aStanding on the moon, I''m feeling so alone and blue\u000aI see the Gulf of Mexico as tiny as a tear\u000aThe coast of California must be somewhere over here\u000aOver here\u000a\u000aStanding on the moon, I see the battle rage below\u000aStanding on the moon, I see the soldiers come and go\u000aThere''s a metal flag beside me someone planted long ago\u000aOld glory standing stiffly, crimson, white and indigo\u000aOld glory standing stiffly, crimson, white and indigo\u000aIndigo\u000a\u000aI see all of South East Asia; I can see El Salvador\u000aI hear the cries of children and the other songs of war\u000aIt''s like a mighty melody that rings down from the sky\u000aStanding here upon the moon I watch it all roll by\u000aAll roll by\u000aAll roll by\u000aAll roll by\u000a\u000aStanding on the moon, I see a shadow on the sun\u000aStanding on the moon, the stars go fading one by one\u000aI hear a cry of victory, another of defeat\u000aA scrap of age-old lullaby down some forgotten street\u000a\u000aStanding on the moon, where talk is cheap and vision true\u000aStanding on the moon, but I would rather be with you\u000aSomewhere in San Francisco on a back porch in July\u000aJust looking up to heaven at this crescent in the sky\u000aIn the sky\u000a\u000aStanding on the moon with nothing left to do\u000aA lovely view of heaven but I''d rather be with you\u000aA lovely view of heaven but I''d rather be with you\u000aBe with you\u000aI''d rather be with you\u000a[etc]'),'Standing on the Moon Score.pdf',7,NULL,NULL,18,3);
INSERT INTO Song VALUES(36,'Hell in a Bucket','hell-in-a-bucket',unistr('Well I was drinking last night with a biker\u000aAnd I showed him a picture of you\u000aI said "pal, get to know her, you''ll like her"\u000aSeemed like the least I could do\u000a\u000a''Cause when he''s charging his chopper\u000aUp and down your carpeted halls\u000aYou will think me by contrast quite proper\u000aNever mind how I stumble and fall\u000aNever mind how I stumble and fall\u000a\u000aChorus\u000aYou imagine sipping champagne from your boot\u000aFor a taste of your elegant pride\u000aI may be going to hell in a bucket\u000aBut at least I''m enjoying the ride\u000aAt least I''m enjoying the ride\u000aYeah at least I''m enjoying the ride\u000a\u000aAhh miss sweetie little soft-core pretender\u000aSomehow baby got hard as it gets\u000aWith her black leather chrome spiked suspenders\u000aAnd her chair and her whip and her pets\u000a\u000aWell we know you''re the reincarnation\u000aOf the ravenous Catherine the Great\u000aAnd we know how you love your ovations\u000aAnd the Z-rated scenes you create\u000aAnd the Z-rated scenes you create\u000a\u000aChorus\u000a\u000aYou analyse me, attempt to despise me\u000aAnd you laugh when I stumble and fall\u000aThere may come a day I will dance on your grave\u000aIf unable to dance I will crawl across it\u000aUnable to dance I will crawl\u000aYeah, unable to dance I''ll crawl\u000a\u000aYou must really consider the circus\u000a''Cause it just might be your kind of zoo\u000aI can''t think of a place that''s more perfect\u000aFor a person as perfect as you\u000a\u000aAnd it''s not like I''m leaving you lonely\u000a''Cause I wouldn''t know where to begin\u000aBut I know that you''ll think of me only\u000aWhen the snakes come marching in\u000aWhen the snakes come marching in\u000a\u000aChorus\u000a\u000aRide, ride, ride, ride\u000aAt least I''m enjoying the ride\u000aRide, ride, ride, ride\u000aAt least I''m enjoying the ride\u000aRide, ride, ride\u000aAt least I''m enjoying the ride'),'Hell in a Bucket Score.pdf',2,NULL,NULL,17,1);
INSERT INTO Song VALUES(37,'High Time','high-time',unistr('You told me goodbye\u000aHow was I to know\u000aYou didn''t mean goodbye\u000aYou meant please don''t let me go\u000aI was having a high time\u000aLiving the good life\u000aWell I know\u000a\u000aThe wheels are muddy\u000aGot a ton of hay\u000aNow listen here baby\u000a''Cause I mean what I say\u000aI''m having a hard time\u000aLiving the good life\u000aWell I know\u000a\u000aI was losing time, I had nothing to do\u000aNo-one to fight, I came to you\u000aWheels broke down, the leader won''t draw\u000aThe line is busted, the last one I saw\u000a\u000aTomorrow comes trouble\u000aTomorrow comes pain\u000aNow don''t think too hard, baby\u000a''Cause you know what I''m saying\u000aI could show you a high time\u000aLiving the good life\u000aDon''t be that way\u000a\u000aNothing''s for certain\u000aIt could always go wrong\u000aCome in when it''s raining\u000aGo on out when it''s gone\u000aWe could have us a high time\u000aLiving the good life\u000aWell I know'),'High Time Score.pdf',2,NULL,NULL,5,3);
INSERT INTO Song VALUES(38,'Jack Straw','jack-straw',unistr('[All]\u000aWe can share the women, we can share the wine\u000aWe can share what we got of yours, ''cause we done shared all of mine\u000aKeep on rolling, just a mile to go\u000aKeep on rolling, my old buddy, you''re moving much too slow\u000a\u000a[Jerry] x\u000aI just jumped the watchman right outside the fence\u000aTook his rings, four bucks in change, ain''t that heaven sent\u000a[Bob]\u000aHurts my ears to listen, Shannon, burns my eyes to see\u000aCut down a man in cold blood, Shannon, might as well be me\u000a\u000a[Bob]\u000aWe used to play for silver now we play for life\u000aAnd one''s for sport, and one''s for blood at the point of a knife\u000aAnd now the die is shaken, now the die must fall\u000aThere ain''t a winner in the game\u000aHe don''t go home with all, not with all\u000a\u000a[All]\u000aLeaving Texas, fourth day of July\u000aSun so hot, the clouds so low, the eagles filled the sky\u000aCatch the Detroit Lightning out of Santa Fe\u000aThe Great Northern out of Cheyenne, from sea to shining sea\u000a\u000a[Jerry]\u000aGotta go to Tulsa, first train we can ride\u000aGotta settle one old score, one small point of pride\u000a[Bob]\u000aThere ain''t a place a man can hide, Shannon, will keep him from the sun\u000aAin''t a bed can give us rest now, you keep us on the run\u000a\u000a[All]\u000aJack Straw from Wichita cut his buddy down\u000aAnd dug for him a shallow grave, and laid his body down\u000aHalf a mile from Tucson, by the morning light\u000a\u000aOne man gone and another to go\u000aMy old buddy you''re moving much too slow\u000a\u000aWe can share the women we can share the wine'),'Jack Straw Score.pdf',4,NULL,NULL,10,1);
INSERT INTO Song VALUES(39,'I Need a Miracle','i-need-a-miracle',unistr('I need a woman ''bout twice my age\u000aA lady of nobility, gentility and rage\u000aA splendour in the dark, lightning on the draw\u000aWho''ll go right through the book and break each and every law\u000a\u000aI got a feelin''\u000aAnd it won''t go away, oh no\u000aJust one thing and I''ll be OK\u000aI need a miracle every day\u000a\u000aI need a woman ''bout twice my height\u000aStatuesque, raven-tressed, a goddess of the night\u000aA secret incantation, candle burning blue\u000aWe''ll consult the spirits, maybe they''ll know what to do\u000a\u000aAnd it''s real\u000aAnd it won''t go away, oh no\u000aCan''t get around and I can''t run away\u000aI need a miracle every day\u000a\u000aI need a woman ''bout twice my weight\u000aA ton of fun who packs a gun with all that other freight\u000aFind her in a side-show, leave her in LA\u000aRide her like a surfer riding on a tidal wave\u000a\u000aAnd it''s real\u000aBelieve what I say\u000aJust one thing that I gotta say\u000aI need a miracle very day\u000a\u000aIt takes dynamite to get me up\u000aToo much of everything is just enough\u000aOne more thing that I gotta say\u000aI need a miracle every day'),'I Need a Miracle Score.pdf',6,NULL,NULL,14,1);
INSERT INTO Song VALUES(40,'I Know You Rider','i-know-you-rider',unistr('Chorus\u000aI know you, rider, gonna miss me when I''m gone;\u000aI know you, rider, gonna miss me when I''m gone;\u000aGonna miss your baby, from rolling in your arms.\u000a\u000aLaid down last night, Lord, I could not take my rest;\u000aLaid down last night, Lord, I could not take my rest;\u000aMy mind was wandering like the wild geese in the West.\u000a\u000aThe Sun will shine in my back door someday.\u000aThe Sun will shine in my back door someday.\u000aMarch winds will blow all my troubles away.\u000a\u000aI wish I was a headlight, on a North bound train;\u000aI wish I was a headlight, on a North bound train;\u000aI''d shine my light through cool Colorado rain.\u000a\u000aChorus'),'I Know You Rider Score.pdf',7,NULL,'cover',10,3);
INSERT INTO Song VALUES(41,'Help on the Way / Slipknot!','help-on-the-way-slipknot',unistr('Paradise waits\u000aOn the crest of a wave her angels in flame\u000aShe has no pain\u000aLike a child she is pure, she is not to blame\u000aPoised for flight, wings spread bright\u000aSpring from night into the sun\u000aDon''t stop to run\u000aShe can fly like a lie, she can''t be outdone\u000a\u000aTell me the cost\u000aI can pay, let me go, tell me love is not lost\u000aSell everything\u000aWithout love day to day, insanity''s king\u000aI will pay, day by day\u000aAnyway, lock, bolt and key\u000aCrippled but free\u000aI was blind all the time I was learning to see\u000a\u000aHelp on the way\u000aWell I know only this, I''ve got you today\u000aDon''t fly away\u000a''Cause I love what I love and I want it that way\u000aI will stay, one more day\u000aLike I say, honey, it''s you\u000aMaking it too\u000aWithout love in the dream it''ll never come true'),'Help on the Way Score.pdf',1,NULL,NULL,13,3);
INSERT INTO Song VALUES(42,'Playing in the Band','playing-in-the-band',unistr('Some folks trust to reason, others trust to might\u000aI don''t trust to nothing, but I know it come out right\u000aSay it once again now, whoa I hope you understand\u000aWhen it''s done and over, Lord, a man is just a man\u000a\u000aChorus\u000aPlaying, playing in the band\u000aDaybreak, daybreak on the land\u000a\u000aSome folks look for answers, others look for fights\u000aSome folks up in tree tops, just looking for their kites\u000aI can tell your future, whoa just look what''s in your hand\u000aI can''t stop for nothing, I''m just playing in the band\u000a\u000aChorus\u000a\u000aStanding on a tower, world at my command\u000aYou just keep a-turning, while I''m playing in the band\u000aIf a man among you, got no sin upon his hand\u000aLet him cast a stone at me for playing in the band\u000a\u000aChorus\u000a\u000aChorus\u000aChorus\u000aPlaying, like a wave upon the sand\u000aDaybreak, while I''m playing in the band'),'Playing in the Band Score.pdf',4,NULL,NULL,7,1);
INSERT INTO Song VALUES(43,'Brown-Eyed Women','brown-eyed-women',unistr('Gone are the days when the ox fall down\u000aTake up the yoke and plow the fields around\u000aGone are the days when the ladies said "please\u000aGentle Jack Jones won''t you come to me"\u000a\u000aChorus\u000aBrown-eyed women and red grenadine\u000aThe bottle was dusty but the liquor was clean\u000aSound of the thunder with the rain pouring down\u000aAnd it looks like the old man''s getting on\u000a\u000aNineteen twenty when he stepped to the bar\u000aDrank to the dregs of the whiskey jar\u000aNineteen thirty when the Wall caved in\u000aHe made his way selling red-eyed gin\u000a\u000aChorus\u000a\u000aDelilah Jones was the mother of twins\u000aTwo times over and the rest were sins\u000aRaised eight boys, only I turned bad\u000aDidn''t get the lickings that the other ones had\u000a\u000aChorus\u000a\u000aTumble-down shack in Big Foot County\u000aSnowed so hard that the roof caved in\u000aDelilah Jones went to meet her God\u000aAnd the old man never was the same again\u000a\u000aDaddy made whiskey and he made it well\u000aCost two dollars and it burned like hell\u000aI cut hickory just to fire the still\u000aDrink down a bottle and you''re ready to kill ,\u000a\u000aChorus\u000a\u000aAnd it looks like the old man''s getting on'),'Brown-Eyed Women Score.pdf',8,NULL,NULL,10,3);
INSERT INTO Song VALUES(44,'Box of Rain','box-of-rain',unistr('Look out of any window\u000aAny morning, any evening, any day\u000aMaybe the sun is shining\u000aBirds are winging, no rain is falling from a heavy sky\u000aWhat do you want me to do\u000aTo do for you to see you through?\u000aFor this is all a dream we dreamed one afternoon long ago\u000a\u000aWalk out of any doorway\u000aFeel your way like the day before\u000aMaybe you''ll find direction\u000aAround some corner where it''s been waiting to meet you\u000aWhat do you want me to do\u000aTo watch for you while you''re sleeping?\u000aThen please don''t be surprised when you find me dreaming too\u000a\u000a\u000aLook into any eyes\u000aYou find by you; you can see clear to another day\u000aMaybe been seen before\u000aThrough other eyes on other days while going home\u000aWhat do you want me to do\u000aTo do for you to see you through?\u000aIt''s all a dream we dreamed one afternoon long ago\u000a\u000aWalk into splintered sunlight\u000aInch your way through dead dreams to another land\u000aMaybe you''re tired and broken\u000aYour tongue is twisted with words half spoken and thoughts unclear\u000aWhat do you want me to do\u000aTo do for you, to see you through?\u000aA box of rain will ease the pain and love will see you through\u000a\u000aJust a box of rain, wind and water\u000aBelieve it if you need it, if you don''t just pass it on\u000aSun and shower, wind and rain\u000aIn and out the window like a moth before a flame\u000a\u000aAnd it''s just a box of rain, I don''t know who put it there\u000aBelieve it if you need it or leave it if you dare\u000aAnd it''s just a box of rain, or a ribbon for your hair\u000aSuch a long, long time to be gone and a short time to be there'),'Box of Rain Score.pdf',1,NULL,NULL,6,4);
INSERT INTO Song VALUES(45,'Casey Jones','casey-jones',unistr('Chorus\u000aDriving that train, high on cocaine\u000aCasey Jones you''d better watch your speed\u000aTrouble ahead, trouble behind\u000aAnd you know that notion just crossed my mind\u000a\u000aThis old engine makes it on time\u000aLeaves Central Station ''bout a quarter to nine\u000aHits River Junction at seventeen to\u000aAt a quarter to ten you know it''s travelling again\u000a\u000aChorus\u000a\u000aTrouble ahead, the lady in red\u000aTake my advice you''d be better off dead\u000aSwitchman''s sleeping, train Hundred and Two\u000aIs on the wrong track and headed for you\u000a\u000aChorus\u000a\u000aTrouble with you is the trouble with me\u000aGot two good eyes but we still don''t see\u000aCome round the bend, you know it''s the end\u000aThe fireman screams and the engine just gleams\u000a\u000aChorus - repeated'),'Casey Jones Score.pdf',8,NULL,NULL,5,3);
INSERT INTO Song VALUES(46,'Truckin''','truckin',unistr('Truckin'' got my chips cashed in\u000aKeep truckin'' like the doodah man\u000aTogether, more or less in line\u000aJust keep truckin'' on\u000a\u000aArrows of neon and flashing marquees out on Main Street\u000aChicago, New York, Detroit and it''s all the same street\u000aYour typical city involved in a typical daydream\u000aHang it up and see what tomorrow brings\u000a\u000aDallas got a soft machine\u000aHouston too close to New Orleans\u000aNew York got the ways and means\u000aBut just won''t let you be\u000a\u000aMost of the cats that you meet on the street speak of true love\u000aMost of the time they''re sitting and crying at home\u000aOne of these days they know they gotta get going\u000aOut of the door and down to the street all alone\u000a\u000aTruckin'' like the doodah man\u000aOnce told me "Gotta play your hand\u000aSometimes the cards ain''t worth a dime\u000aIf you don''t lay them down"\u000a\u000aSometimes the lights all shining on me\u000aOther times I can barely see\u000aLately it occurs to me\u000aWhat a long strange trip it''s been\u000a\u000aWhat in the world ever became of sweet Jane?\u000aShe lost her sparkle you know she isn''t the same\u000aLiving on reds and vitamin C and cocaine\u000aAll her friends can say is ain''t it a shame\u000a\u000aTruckin'' up to Buffalo\u000aBeen thinking you got to mellow slow\u000aTakes time, you pick a place to go\u000aJust keep truckin'' on\u000a\u000aSitting and staring out of the hotel window\u000aGot a tip they''re gonna kick the door in again\u000aLike to get some sleep before I travel\u000aBut if you got a warrant I guess you''re gonna come in\u000a\u000aBusted down on Bourbon Street\u000aSet up like a bowling pin\u000aKnocked down, it gets to wearing thin\u000aThey just won''t let you be\u000a\u000aYou''re sick of hanging around, you''d like to travel\u000aGet tired of travelling you want to settle down\u000aI guess they can''t revoke your soul for trying\u000aGet out of the door, light out and look all around\u000a\u000aSometimes the lights all shining on me\u000aOther times I can barely see\u000aLately it occurs to me\u000aWhat a long strange trip it''s been\u000a\u000aTruckin'' I''m a going home\u000aWhoa, whoa, baby, back where I belong\u000aBack home, sit down and patch my bones\u000aAnd get back truckin'' on'),'Truckin'' Score.pdf',10,NULL,NULL,6,1);
INSERT INTO Song VALUES(47,'Althea','althea',unistr('I told Althea I was feeling lost\u000aLacking in some direction\u000aAlthea told me upon scrutiny\u000aThat my back might need protection\u000aI told Althea that treachery\u000aWas tearing me limb from limb\u000aAlthea told me, now cool down boy\u000aSettle back easy, Jim\u000a\u000aYou may be Saturday''s child all grown\u000aMoving with a pinch of grace\u000aYou may be a clown in the burying ground\u000aOr just another pretty face\u000aYou may be the fate of Ophelia\u000aSleeping and perchance to dream\u000aHonest to the point of recklessness\u000aSelf-centred to the extreme\u000a\u000aAin''t nobody messin'' with you but you\u000aYour friends are getting most concerned\u000aLoose with the truth, maybe its your fire\u000aBaby, I hope you don''t get burned\u000aWhen the smoke has cleared, she said\u000aThat''s what she said to me\u000aYou''re gonna want a bed to lay your head\u000aAnd a little sympathy\u000a\u000aThere are things you can replace\u000aAnd others you cannot\u000aThe time has come to weigh those things\u000aThis space is gettin'' hot\u000aYou know this space is gettin'' hot\u000a\u000aI told Althea, I''m a roving sign\u000aThat I was born to be a bachelor\u000aAlthea told me, OK that''s fine\u000aSo now I''m trying to catch her\u000aCan''t talk to you without talking to me\u000aWe''re guilty of the same old thing\u000aThinking a lot about less and less\u000aAnd forgetting the love we bring'),'Althea Score.pdf',3,NULL,NULL,16,3);
INSERT INTO Song VALUES(48,'China Cat Sunflower','china-cat-sunflower',unistr('Look for a while at the China Cat Sunflower\u000aproud-walking jingle in the midnight sun\u000aCopper-dome bodhi drip a silver kimono\u000alike a crazy-quilt star gown\u000athrough a dream night wind\u000a\u000aChorus\u000aChina cat\u000aChina cat\u000aChina cat\u000aChina cat\u000a\u000aKrazy Kat peeking through a lace bandana\u000alike a one-eyed Cheshire\u000alike a diamond-eyed jack\u000aA leaf of all colors plays\u000aa golden string fiddle\u000ato a double-e waterfall over my back\u000a\u000aChorus\u000a\u000aComic book colors on a violin river\u000acrying Leonardo words\u000afrom out a silk trombone\u000aI rang a silent bell\u000abeneath a shower of pearls\u000ain the eagle winged palace\u000aof the queen Chinee\u000a\u000aChorus'),'China Cat Sunflower Score.pdf',6,NULL,NULL,10,3);
INSERT INTO Song VALUES(49,'Brokedown Palace','brokedown-palace',unistr('Fare you well, my honey\u000aFare you well, my only true one\u000aAll the birds that were singing\u000aAre flown, except you alone\u000a\u000aGonna leave this brokedown palace\u000aOn my hands and my knees, I will roll, roll, roll\u000aMake myself a bed by the waterside\u000aIn my time, in my time, I will roll, roll, roll\u000a\u000aIn a bed, in a bed\u000aBy the waterside I will lay my head\u000aListen to the river sing sweet songs\u000aTo rock my soul\u000a\u000aRiver gonna take me, sing me sweet and sleepy\u000aSing me sweet and sleepy all the way back home\u000aIt''s a far gone lullaby sung many years ago\u000aMama, Mama, many worlds I''ve come since I first left home\u000a\u000aGoing home, going home\u000aBy the waterside I will rest my bones\u000aListen to the river sing sweet songs\u000aTo rock my soul\u000a\u000aGoing to plant a weeping willow\u000aOn the bank''s green edge it will grow, grow, grow\u000aSinging a lullaby beside the water\u000aLovers come and go, the river will roll, roll, roll\u000a\u000aFare you well, fare you well\u000aI love you more than words can tell\u000aListen to the river sing sweet songs\u000aTo rock my soul'),'Brokedown Palace Score.pdf',7,NULL,NULL,6,3);
INSERT INTO Song VALUES(50,'Candyman','candyman',unistr('Come all you pretty women with your hair a-hanging down\u000aOpen up your windows, ''cause the Candyman''s in town\u000aCome on boys and gamble\u000aRoll those laughing bones\u000aSeven come eleven, boys, I''ll take your money home\u000a\u000aChorus\u000aLook out, look out, the Candyman\u000aHere he comes and he''s gone again\u000aPretty lady ain''t got no friend\u000aTill the Candyman comes around again\u000a\u000aI come in from Memphis where I learnt to talk the jive\u000aWhen I get back to Memphis, be one less man alive\u000aGood morning, Mister Benson\u000aI see you''re doing well\u000aIf I had me a shotgun, I''d blow you straight to hell\u000a\u000aChorus\u000a\u000aCome on boys and wager, if you have got the mind\u000aIf you''ve got a dollar, boys, lay it on the line\u000aHand me my old guitar\u000aPass the whiskey round\u000aWon''t you tell everybody you meet that the Candyman''s in town\u000a\u000aChorus\u000a\u000aLook out, look out, the Candyman\u000aHere he come and he''s gone again\u000a[repeat and fade]'),'Candyman Score.pdf',5,NULL,NULL,6,3);
INSERT INTO Song VALUES(51,'Not Fade Away','not-fade-away',unistr('I wanna tell you how it''s gonna be, you''re gonna give your love to me,\u000aI wanna love you night and day, you know my love not fade away.\u000a\u000aYou know my love not fade away, not fade away!\u000a\u000aMy love is bigger than a Cadillac, I try to show you but you drive me back,\u000aYour love for me has got to be real, your gonna know just how I feel.\u000a\u000aOur love is real, not fade away, not fade away!'),'Not Fade Away Score.pdf',11,NULL,'cover',7,1);
INSERT INTO Song VALUES(52,'Morning Dew','morning-dew',unistr('Walk me out in the morning dew my honey,\u000aWalk me out in the morning dew today.\u000aI cant walk you out in the morning dew my honey,\u000aI cant walk you out in the morning dew today.\u000a\u000aI thought i heard a baby cry this morning,\u000aI thought i heard a baby cry this today.\u000aYou didn’t hear no baby cry this morning,\u000aYou didn’t hear no baby cry today.\u000a\u000aWhere have all the people gone my honey,\u000aWhere have all the people gone today.\u000aTheres no need for you to be worrying about all those people,\u000aYou never see those people anyway.\u000a\u000aI thought i heard a young man morn this morning,\u000aI thought i heard a young man morn today.\u000aI thought i heard a young man morn this morning,\u000aI cant walk you out in the morning dew today.\u000aWalk me out in the morning dew my honey,\u000aWalk me out in the morning dew today.\u000aIll walk you out in the morning dew my honey,\u000aI guess it doesn’t really matter anyway,\u000aI guess it doesn’t matter anyway,\u000aI guess it doesn’t matter anyway,\u000aGuess it doesn’t matter anyway.'),'Morning Dew Score.pdf',7,NULL,'cover',1,3);
INSERT INTO Song VALUES(53,'St. Stephen','st-stephen',unistr('Saint Stephen with a rose\u000aIn and out of the garden he goes\u000aCountry garland in the wind and the rain\u000aWherever he goes the people all complain\u000a\u000aStephen prosper in his time\u000aWell he may, and he may decline\u000aDid it matter, does it now?\u000aStephen would answer if he only knew how\u000a\u000aWishing well with a golden bell\u000aBucket hanging clear to hell\u000aHell half way twixt now and then\u000aStephen fill it up and lower down, and lower down again\u000a\u000aLady finger, dipped in moonlight\u000aWriting "What for?" across the morning sky\u000aSunlight splatters dawn with answers\u000aDarkness shrugs and bids the day goodbye\u000a\u000aSpeeding arrow, sharp and narrow\u000aWhat a lot of fleeting matters you have spurned\u000aSeveral seasons with their treasons\u000aWrap the babe in scarlet colors, call it your own\u000a\u000aDid he doubt or did he try?\u000aAnswers a-plenty in the by and by\u000aTalk about your plenty, talk about your ills\u000aOne man gathers what another man spills\u000a\u000aSaint Stephen will remain\u000aAll he''s lost he shall regain\u000aSeashore washed by the suds and the foam\u000aBeen here so long he''s got to calling it home\u000a\u000aFortune comes a-crawling, Calliope woman\u000aSpinning that curious sense of your own\u000aCan you answer? Yes I can\u000aBut what would be the answer to the answer man?\u000a\u000a-----(William Tell Bridge)-----\u000aHigh green chilly winds and windy vines in loops\u000aAround the twining shafts of lavender (Note 4)\u000aThey''re crawling to the sun\u000a\u000aUnderfoot the ground is patched\u000aWith climbing arms of ivy wrapped\u000aAround the manzanita stark and shiny in the breeze\u000a\u000aWonder who will water all the children of the garden\u000aWhen they sigh about the barren lack\u000aOf rain and droop so hungry ''neath the sky\u000a\u000aWilliam Tell has stretched his bow\u000aTill it won''t stretch no furthermore\u000aAnd/or it will require a change that hasn''t come before (Note 5)'),'St. Stephen Score.pdf',1,NULL,NULL,3,NULL);
INSERT INTO Song VALUES(54,'Sugaree','sugaree',unistr('When they come to take you down\u000aWhen they bring that wagon round\u000aWhen they come to call on you\u000aAnd drag your poor body down\u000a\u000aChorus\u000aJust one thing I ask of you\u000aJust one thing for me\u000aPlease forget you knew my name\u000aMy darling, Sugaree\u000a\u000aShake it, shake it, Sugaree\u000aJust don''t tell them that you know me\u000aShake it, shake it, Sugaree\u000aJust don''t tell them that you know me\u000a\u000aYou thought you was the cool fool\u000aAnd never would do no wrong\u000aYou had everything sewed up tight\u000aHow come you lay awake all night long\u000a\u000aChorus\u000a\u000aWell in spite of all you gained\u000aYou still have to stand out in the pouring rain\u000aOne last voice is calling you\u000aAnd I guess it''s time you go\u000a\u000aChorus\u000a\u000aWell shake it up now, Sugaree\u000aI''ll meet you at the jubilee\u000aAnd if that jubilee don''t come\u000aMaybe I''ll meet you on the run\u000a\u000aChorus'),'Sugaree Score.pdf',3,NULL,NULL,9,3);
INSERT INTO Song VALUES(55,'Sugar Magnolia','sugar-magnolia',unistr('Sugar Magnolia, blossoms blooming\u000aHead''s all empty and I don''t care\u000aSaw my baby down by the river\u000aKnew she''d have to come up soon for air\u000a\u000aSweet blossom, come on under the willow\u000aWe can have high times if you''ll abide\u000aWe can discover the wonders of nature\u000aRolling in the rushes down by the riverside\u000a\u000aShe''s got everything delightful\u000aShe''s got everything I need\u000aTakes the wheel when I''m seeing double\u000aPays my ticket when I speed\u000a\u000aShe comes skimming through rays of violet\u000aShe can wade in a drop of dew\u000aShe don''t come and I don''t follow\u000aWaits backstage while I sing to you\u000a\u000aShe can dance  a Cajun rhythm\u000aJump like a Willys in four wheel drive\u000aShe''s a summer love in the spring, fall and winter\u000aShe can make happy any man alive\u000a\u000aSugar Magnolia\u000aRinging that bluebell\u000aCaught up in sunlight\u000aCome on out singing and I''ll walk you in the sunshine\u000aCome on honey, come along with me\u000a\u000aShe''s got everything delightful\u000aShe''s got everything I need\u000aA breeze in the pines and the summer night moonlight\u000aLazing in the sunlight, yes indeed\u000a\u000aSometimes when the cuckoo''s crying\u000aWhen the moon is half way down\u000aSometimes when the night is dying\u000aI take me out and I wander around\u000aI wander round\u000a\u000aSunshine Daydream\u000a\u000aSunshine daydream\u000aWalk you in the tall trees\u000aGoing where the wind goes\u000aBlooming like a red rose\u000aBreathing more freely\u000aLight out singing\u000aI''ll walk you in the morning sunshine\u000aSunshine daydream\u000aSunshine daydream\u000aWalking in the sunshine\u000a[etc]'),'Sugar Magnolia Score.pdf',3,NULL,NULL,6,1);
INSERT INTO Song VALUES(56,'Throwing Stones','throwing-stones',unistr('Picture a bright blue ball just spinning, spinning free\u000aDizzy with eternity\u000aPaint it with a skin of sky, brush in some clouds and sea\u000aCall it home for you and me\u000aA peaceful place, or so it looks from space\u000aA closer look reveals the human race\u000aFull of hope, full of grace, is the human race\u000aBut afraid we may lay our home to waste\u000a\u000aThere''s a fear down here we can''t forget\u000aHasn''t got a name just yet\u000aAlways awake, always around\u000aSinging ashes, ashes, all fall down\u000aAshes, ashes, all fall down\u000a\u000aNow watch as the ball revolves and the night-time falls\u000aAnd again the hunt begins and again the blood wind calls\u000aBy and by, again, the morning sun will rise\u000aBut the darkness never goes from some men''s eyes\u000a(Well I know)\u000aIt strolls the sidewalk and it rolls the streets\u000aStaking turf, dividing up meat\u000aNightmare spook, piece of heat\u000aIt''s you and me, you and me\u000a\u000aClick flash blade in ghetto night\u000aRudy''s looking for a fight\u000aRat cat alley, roll them bones\u000aNeed that cash to feed that Jones\u000aAnd the politicians throwing stones\u000aSinging ashes, ashes, all fall down\u000aAshes, ashes, all fall down\u000a\u000aCommissars and pinstripe bosses roll the dice\u000aAnyway they fall, guess who gets to pay the price?\u000aMoney green, or proletarian gray\u000aSelling guns instead of food today\u000aSo the kids they dance and shake their bones\u000aAnd the politicians throwing stones\u000aSinging ashes, ashes, all fall down\u000aAshes, ashes, all fall down\u000a\u000aHeartless powers try to tell us what to think\u000aIf the spirit''s sleeping then the flesh is ink\u000aHistory''s page will be neatly carved in stone\u000aThe future''s here, we are it, we are on our own\u000aOn our own, on our own, we are on our own\u000a\u000aIf the game is lost, then we''re all the same\u000aNo one left to place or take the blame\u000aWe will leave this place an empty stone\u000aOr that shining ball of blue we call our home\u000a\u000aSo the kids, they dance, they shake their bones\u000aAnd the politicians throwing stones\u000aSinging ashes, ashes, all fall down\u000aAshes, ashes, all fall down\u000a\u000aShipping powders back and forth\u000aSinging black goes south and white comes north\u000aAnd the whole world full of petty wars\u000aSinging I got mine and you got yours\u000aWhile the current fashions set the pace\u000aLose your step, fall out of grace\u000aThe radical, he rant and rage\u000aSinging someone got to turn the page\u000aAnd the rich man in his summer home\u000aSinging just leave well enough alone\u000aBut his pants are down, his cover''s blown\u000aAnd the politicians throwing stones\u000aSo the kids, they dance, they shake their bones\u000a''Cause it''s all too clear we''re on our own\u000aSinging ashes, ashes, all fall down\u000aAshes, ashes, all fall down\u000a\u000aPicture a bright blue ball just spinning, spinning free\u000aIt''s dizzying, the possibilities\u000a\u000aAshes, ashes, all fall down\u000a[Ashes, ashes, all fall down]\u000aAshes, ashes, all fall down\u000a[Ashes, ashes, all fall down]\u000aAshes, ashes, all fall down\u000a[Ashes, ashes, all fall down]\u000aAshes, ashes, all fall down\u000a[Ashes, ashes, all fall down]\u000a[etc]'),'Throwing Stones Score.pdf',6,NULL,NULL,17,1);
INSERT INTO Song VALUES(57,'The Wheel','the-wheel',unistr('Chorus 1\u000aThe wheel is turning and you can''t slow down\u000aYou can''t let go and you can''t hold on\u000aYou can''t go back and you can''t stand still\u000aIf the thunder don''t get you then the lightning will\u000a\u000aChorus 2\u000aWon''t you try just a little bit harder\u000aCouldn''t you try just a little bit more\u000aWon''t you try just a little bit harder\u000aCouldn''t you try just a little bit more\u000a\u000aRound, round, Robin run around\u000aGotta get back where you belong\u000aLittle bit harder, just a little bit more\u000aLittle bit further than you gone before\u000a\u000a[chorus 1]\u000a\u000aSmall wheel turning by the fire and rod\u000aBig wheel turning by the grace of God\u000aEvery time that wheel turn round\u000aBound to cover just a little more ground\u000a\u000a[chorus 1]\u000a\u000a[chorus 2]'),'The Wheel Score.pdf',10,NULL,NULL,9,3);
INSERT INTO Song VALUES(58,'West L.A. Fadeaway','west-la-fadeaway',unistr('Looking for a chateau\u000aTwenty one rooms but one will do\u000aLooking for a chateau\u000aTwenty one rooms but one will do\u000aI don''t want to buy it\u000aI just want to rent it for an hour or two\u000a\u000aMet an old mistake\u000aWalking down the street today\u000aMet an old mistake\u000aWalking down the street today\u000aI didn''t want to be mean about it\u000aBut I, I didn''t have one good word to say\u000a\u000aChorus\u000aWest L.A. fadeaway\u000aWest L.A. fadeaway\u000aLittle red light on the highway\u000aBig green light on the speedway, hey, hey, hey\u000a\u000aI had a steady job\u000aHauling items for the mob\u000aI had a steady job\u000aHauling items for the mob\u000aYou know the pay was pathetic\u000aIt''s a shame those boys couldn''t be more copacetic\u000a\u000aI met a west L.A. girl\u000aAlready know what I need to know\u000aI met a west L.A. girl\u000aAlready know what I need to know\u000aName, address and phone number, Lord\u000aAnd just how far to go\u000a\u000aChorus\u000a\u000aLooking for a chateau\u000aTwenty one rooms but one will do\u000aLooking for a chateau\u000aTwenty one rooms but one will do\u000aI don''t want to rent it\u000aI just what to use it for a minute or two\u000a\u000aChorus\u000a\u000aLittle red light on the highway\u000aBig green light on the speedway, hey, hey, hey\u000aLittle red light on the highway\u000aBig green light on the speedway, hey, hey, hey'),'West L.A. Fadeaway Score.pdf',4,NULL,NULL,17,3);
INSERT INTO Song VALUES(59,'Attics of My Life','attics-of-my-life',unistr('In the attics of my life\u000aFull of cloudy dreams unreal\u000aFull of tastes no tongue can know\u000aAnd lights no eye can see\u000aWhen there was no ear to hear\u000aYou sang to me\u000a\u000aI have spent my life\u000aSeeking all that''s still unsung\u000aBent my ear to hear the tune\u000aAnd closed my eyes to see\u000aWhen there were no strings to play\u000aYou played to me\u000a\u000aIn the book of love''s own dreams\u000aWhere all the print is blood\u000aWhere all the pages are my days\u000aAnd all my lights grow old\u000a\u000aWhen I had no wings to fly\u000aYou flew to me\u000aYou flew to me\u000a\u000aIn the secret space of dreams\u000aWhere I dreaming lay amazed\u000aWhen the secrets all are told\u000aAnd the petals all unfold\u000aWhen there was no dream of mine\u000aYou dreamed of me'),'Attics of My Life Score.pdf',9,NULL,NULL,6,NULL);
INSERT INTO Song VALUES(60,'Franklin''s Tower','franklins-tower',unistr('In another time''s forgotten space\u000aYour eyes looked from your mother''s face\u000aWildflower seed on the sand and stone\u000aMay the four winds blow you safely home\u000a\u000aChorus\u000aRoll away the dew\u000aRoll away the dew\u000aRoll away the dew\u000aRoll away the dew\u000a\u000aI''ll tell you where the four winds dwell\u000aIn Franklin''s tower there hangs a bell\u000aIt can ring, turn night to day\u000aIt can ring like fire when you lose your way\u000a\u000aChorus\u000a\u000aGod save the child who rings that bell\u000aIt may have one good ring, baby, you can''t tell\u000aOne watch by night, one watch by day\u000aIf you get confused, listen to the music play\u000a\u000aChorus\u000a\u000aSome come to laugh their past away\u000aSome come to make it just one more day\u000aWhichever way your pleasure tends\u000aIf you plant ice, you''re gonna harvest wind\u000a\u000aChorus\u000a\u000aIn Franklin''s tower the four winds sleep\u000aLike four lean hounds the lighthouse keep\u000aWildflower seed in the sand and wind\u000aMay the four winds blow you home again\u000a\u000aChorus\u000aChorus\u000a[etc]'),'Franklin''s Tower Score.pdf',2,NULL,NULL,13,3);
INSERT INTO Song VALUES(61,'Cumberland Blues','cumberland-blues',unistr('I can''t stay here much longer, Melinda\u000aThe sun is getting high\u000aI can''t help you with your troubles\u000aIf you won''t help with mine\u000aI gotta get down\u000aI gotta get down\u000aGotta get down to the mine\u000a\u000aYou keep me up just one more night\u000aI can''t sleep here no more\u000aLittle Ben clock says quarter to eight\u000aYou kept me up till four\u000aI gotta get down\u000aI gotta get down\u000aOr I can''t work there no more\u000a\u000aLotta poor man make a five dollar bill\u000aWill keep him happy all the time\u000aSome other fellow''s making nothing at all\u000aAnd you can hear him cry\u000a\u000aCan I go, buddy, can I go down\u000aTake your shift at the mine\u000aGotta get down to the Cumberland mine\u000aThat''s where I mainly spend my time\u000a\u000aMake good money, five dollars a day\u000aIf I made any more I might move away\u000a\u000aLotta poor man got the Cumberland Blues\u000aHe can''t win for losing\u000aLotta poor man got to walk the line\u000aJust to pay his union dues\u000a\u000aI don''t know now, I just don''t know\u000aIf I''m going back again\u000aI don''t know now, I just don''t know\u000aIf I''m going back again'),'Cumberland Blues Score.pdf',5,NULL,NULL,5,NULL);
INSERT INTO Song VALUES(62,'Big Railroad Blues','big-railroad-blues',unistr('Well my mama told me, my papa told me too\u000aWell my mama told me, my papa told me too\u000aWell I shouldn''t be here trying to sing these railroad blues\u000a\u000aWish I had listened to oh what mama said\u000aWish I had listened to oh what mama said\u000aWell I wouldn''t be here trying to sleep in this cold iron bed\u000a\u000aWell I went to the depot, I never got there on time\u000aWent down to the depot, never got there on time\u000aWell that train''s rolling down, she''s rolling down the line\u000a\u000aMister jailer go away now, don''t tell me no lies\u000aMister jailer go away now, don''t tell me no lies\u000aWell that train''s going down, she''s rolling down the line\u000a\u000aWell my mama told me, my papa told me too\u000aWell my mama told me, papa told me too\u000aWell I shouldn''t be here trying to sing these railroad blues\u000a\u000aWish I had listened to oh what mama said\u000aWish I had listened to oh what mama said\u000aWell I wouldn''t be here trying to sleep in this cold iron bed'),'Big Railroad Blues Score.pdf',3,NULL,'cover',7,3);
INSERT INTO Song VALUES(63,'Dancin'' in the Streets','dancin-in-the-streets',unistr('Hey, comin'' out around the world be ready for a brand new beat\u000aOh, summer''s here and the time is right, oh, for dancing in the street\u000aDancing in Chicago (dancing in the street)\u000aDown in New Orleans (dancing in the street)\u000aIn New York City (dancing in the street)\u000a\u000aAll we need is music, sweet music (sweet, sweet music)\u000aThey''ll be music everywhere (everywhere)\u000aThey''ll be laughing, singing, music swinging and dancing in the street\u000a\u000aIt doesn''t matter what you wear just as long as you are there\u000aThey''re dancing (dancing in the street) oh oh\u000a\u000aThis is an invitation across the nation the chance for folks to meet\u000aThere''ll be swinging, swaying, music playing and dancing in the street\u000a\u000aPhiladelphia, PA now (dancing in the street)\u000aBaltimore and D.C. (dancing in the street)\u000aCan''t forget them other cities (dancing in the street)'),'Dancin'' in the Streets Score.pdf',2,NULL,'cover',15,1);
INSERT INTO Song VALUES(64,'Bird Song','bird-song',unistr('All I know is something like a bird within her sang\u000aAll I know she sang a little while and then flew on\u000aTell me all that you know\u000aI''ll show you\u000aSnow and rain\u000a\u000aIf you hear that same sweet song again, will you know why?\u000aAnyone who sings a tune so sweet is passing by\u000aLaugh in the sunshine\u000aSing, cry in the dark\u000aFly through the night\u000a\u000aDon''t cry now\u000aDon''t you cry\u000aDon''t you cry any more\u000aLa da da da\u000a\u000aSleep in the stars\u000aDon''t you cry\u000aDry your eyes on the wind\u000aLa da da da da da\u000a\u000aAll I know is something like a bird within her sang\u000aAll I know she sang a little while and then flew on\u000aTell me all that you know\u000aI''ll show you\u000aSnow and rain'),'Bird Song (Studio) Score.pdf',2,NULL,NULL,9,3);
INSERT INTO Song VALUES(65,'Black Muddy River','black-muddy-river',unistr('When the last rose of summer pricks my fingers\u000aAnd the hot sun chills me to the bone\u000aWhen I can''t hear the song for the singer\u000aAnd I can''t tell my pillow from a stone\u000a\u000aI will walk alone by the black muddy river\u000aAnd sing me a song of my own\u000aI will walk alone by the black muddy river\u000aSing me a song of my own\u000a\u000aWhen the last bolt of sunshine hits the mountain\u000aAnd the stars seem to splatter in the sky\u000aWhen the moon splits the south west horizon\u000aAnd scream of an eagle on the fly\u000a\u000aI will walk alone by the black muddy river\u000aAnd listen to the ripples as they moan\u000aI will walk alone by the black muddy river\u000aSing me a song of my own\u000a\u000aBlack muddy river\u000aRoll on forever\u000aI don''t care how deep and wide\u000aIf you got another side\u000aRoll muddy river\u000aRoll muddy river\u000aBlack muddy river, roll\u000a\u000aWhen it seems like the night will last forever\u000aAnd there''s nothing left to do but count the years\u000aWhen the strings of my heart start to sever\u000aAnd stones fall from my eyes instead of tears\u000a\u000aI will walk alone by the black muddy river\u000aAnd dream me a dream of my own\u000aI will walk alone by the black muddy river\u000aSing me a song of my own\u000aAnd sing me a song of my own'),'Black Muddy River Score.pdf',7,NULL,NULL,17,3);
INSERT INTO Song VALUES(66,'Estimated Prophet','estimated-prophet',unistr('My time coming any day, don''t worry ''bout me, no\u000aBeen so long I felt this way, I''m in no hurry no\u000aRainbows end down that highway where ocean breezes blow\u000aMy time coming, voices saying, they tell me where to go\u000aDon''t you worry ''bout me--oh no no, don''t worry ''bout me, no\u000aAnd I''m in no hurry--oh no no no, I know where to go\u000a\u000aCalifornia, preaching on the burning shore\u000aCalifornia, I''ll be knocking on the golden door\u000aLike an angel, standing in a shaft of light\u000aRising up to paradise, I know I''m gonna shine\u000a\u000aMy time coming any day, don''t worry ''bout me, no\u000aIt''s gonna be just like they say, them voices tell me so\u000aSeems so long I felt this way and time sure passing slow\u000aStill I know I lead the way, they tell me where I go\u000a\u000aDon''t you worry ''bout me--oh, no, no, don''t worry ''bout me, no\u000aAnd I''m in no hurry--oh, no, no, no, I know where to go\u000a\u000aCalifornia, a prophet on the burning shore\u000aCalifornia, I''ll be knocking on the golden door\u000aLike an angel, standing in a shaft of light\u000aRising up to paradise, I know I''m gonna shine\u000a\u000aYou''ve all been asleep, you would not believe me\u000aThem voices telling me, you will soon receive me\u000aWe''re standing on the beach, the sea will part before me\u000aFire wheel burning in the air\u000aYou will follow me and we will ride to glory\u000aWay up in the middle of the air\u000aAnd I''ll call down thunder and speak the same\u000aAnd my words fills the sky with flame\u000aAnd might and glory gonna be my name\u000aAnd men gonna light my way\u000a\u000aMy time coming any day, don''t worry ''bout me, no\u000aIt''s gonna be just like they say, them voices tell me so\u000aSeems so long I felt this way and time sure passing slow\u000aMy time coming any day, don''t worry ''bout me, no\u000aDon''t you worry ''bout me--oh, no, no, don''t worry ''bout me, no\u000aAnd I''m in no hurry--oh, no, no, don''t worry ''bout me, no\u000aAnd I''m in no hurry--oh, no, no, no, I know where to go\u000a[etc]'),'Estimated Prophet Score.pdf',1,NULL,NULL,15,1);
INSERT INTO Song VALUES(67,'Don''t Ease Me In','dont-ease-me-in',unistr('Chorus\u000aDon''t ease, don''t ease\u000aDon''t ease me in\u000aI''ve been all night long coming home\u000aDon''t ease me in\u000a\u000aI was standing at the corner\u000aTalking to Miss Brown\u000aWell I turned around, sweet mama\u000aShe was way cross town\u000a\u000aSo I''m walking down the street\u000aWith a dollar in my hand\u000aI''ve been looking for a woman, sweet mama\u000aAin''t got no man\u000a\u000aChorus\u000a\u000aThe girl I love\u000aShe''s sweet and true\u000aYou know the dress she wears, sweet mama\u000aIt''s pink and blue\u000a\u000aShe brings me coffee\u000aYou know she brings me tea\u000aShe brings ''bout every damn thing\u000aBut the jailhouse key\u000a\u000aChorus\u000a\u000aChorus'),'Don''t Ease Me In Score.pdf',9,NULL,'cover',16,3);
INSERT INTO Song VALUES(68,'El Paso','el-paso',unistr('Out in the West Texas town of El Paso\u000aI fell in love with a Mexican girl.\u000aNighttime would find me in Rose''s Cantina,\u000aMusic would play and Felina would whirl.\u000a\u000aBlack as the night were the eyes of Felina,\u000aWicked and evil while casting a spell.\u000aMy love was strong for this Mexican maiden,\u000aI was in love, but in vain I could tell.\u000a\u000aOne night a wild young cowboy came in, wild as the West Texas wind...\u000aDashing and daring, a drink he was sharing,\u000aWith wicked Felina, the girl that I love.\u000a\u000aSo in anger I challenged his right for the love of this maiden;\u000aDown went his hand for the gun that he wore.\u000aMy challenge was answered, in less than a heartbeat\u000aThe handsome young stranger lay dead on the floor.\u000a\u000aJust for a moment I stood there in silence,\u000aShocked by the foul evil deed I had done.\u000aMany thoughts ran through my mind as I stood there;\u000aI had but one chance and that was to run.\u000a\u000aOut through the back door of Rose''s I ran, out where the horses were tied...\u000aI picked a good one; he looked like he could run,\u000aUp on his back and away I did ride.\u000a\u000aJust as fast as I could from the West Texas town of El Paso,\u000aOut through the badlands of New Mexico.\u000aBack in El Paso my life would be worthless;\u000aEverything''s gone in life nothing is left.\u000a\u000aBut it''s been so long since I''ve seen the young maiden,\u000aMy love is stronger that my fear of death.\u000aI saddled up and away I did go, riding alone in the dark...\u000aMaybe tomorrow a bullet may find me,\u000aTonight nothing''s worse than this pain in my heart.\u000a\u000aAnd at last here I am on the hill overlooking El Paso,\u000aI can see Rose''s Cantina below.\u000aMy love is strong and it pushes me onward,\u000adown off the hill to Felina I go.\u000a\u000aOff to my right I see five mounted cowboys,\u000aOff to my left ride a dozen or more.\u000ashouting and shooting; I can''t let them catch me,\u000aI''ve got to make it to Rose''s back door.\u000a\u000aSomething is dreadfully wrong for I feel a deep burning pain in my side\u000aIt''s getting harder to stay in the saddle.\u000aI''m getting weary, unable to ride.\u000a\u000aBut my love for Felina is strong and I rise where I''ve fallen;\u000aThough I am weary, I can''t stop to rest.\u000aI see the white puff of smoke from the rifle,\u000aI feel the bullet go deep in my chest.\u000a\u000aFrom out of nowhere, Felina has found me,\u000aKissing my cheek as she kneels by my side.\u000aCradled by two loving arms that I''ll die for,\u000aOne little kiss and Felina good-bye.'),'El Paso Score.pdf',NULL,NULL,'cover',20,1);
INSERT INTO Song VALUES(69,'Black Peter','black-peter',unistr('All of my friends come to see me last night\u000aI was laying in my bed and dying\u000aAnnie Beauneu from Saint Angel\u000aSay "the weather down here so fine"\u000a\u000aJust then the wind came squalling through the door\u000aBut who can the weather command\u000aJust want to have a little peace to die\u000aAnd a friend or two I love at hand\u000a\u000aFever roll up to a hundred and five\u000aRoll on up, gonna roll back down\u000aOne more day I find myself alive\u000aTomorrow maybe go beneath the ground\u000a\u000aSee here how everything\u000aLead up to this day\u000aAnd it''s just like any other day\u000aThat''s ever been\u000aSun going up and then\u000aThe sun going down\u000aShine through my window\u000aAnd my friends they come around\u000aCome around, come around\u000a\u000aThe people might know, but the people don''t care\u000aThat a man can be as poor as me\u000aTake a look at poor Peter, he''s lying in pain\u000aNow let''s come run and see\u000aRun and see\u000aRun and see\u000aRun, run and see, and see'),'Black Peter Score.pdf',6,NULL,NULL,5,3);
INSERT INTO Song VALUES(70,'Crazy Fingers','crazy-fingers',unistr('Your rain falls like crazy fingers\u000aPeals of fragile thunder\u000aKeeping time\u000aRecall the days that still are to come\u000aSome sing blue\u000a\u000aHang your heart on laughing willow\u000aStray down to the water\u000aDeep sea of love\u000aBeneath the sweet calm face of the sea\u000aSwift undertow\u000a\u000aLife may be sweeter for this, I don''t know\u000aSee how it feels in the end\u000aMay Lady Lullaby sing plainly for you\u000aSoft, strong, sweet and true\u000a\u000aCloud hands reaching from a rainbow\u000aTapping at the window\u000aTouch your hair\u000aSo swift and bright, strange figures of light\u000aFloat in air\u000a\u000aWho can stop what must arrive now?\u000aSomething new is waiting\u000aTo be born\u000aDark as the night you''re still by my side\u000aShining side\u000a\u000aGone are the days we stopped to decide\u000aWhere we should go, we just ride\u000aGone are the broken eyes\u000aWe saw through in dreams\u000aGone, both dream and lie\u000a\u000aLife may be sweeter for this, I don''t know\u000aFeels like it might be alright\u000aMay Lady Lullaby sings plainly for you\u000aLove still rings true\u000a\u000aMidnight on a carousel ride\u000aReaching for the gold ring\u000aDown inside\u000aNever could reach it, just slips away\u000aBut I try'),'Crazy Fingers Score.pdf',5,NULL,NULL,13,3);
INSERT INTO Song VALUES(71,'Friend of the Devil','friend-of-the-devil',unistr('I lit out from Reno, I was trailed by twenty hounds\u000aDidn''t get to sleep that night till the morning came around\u000a\u000aChorus\u000aSet out running but I take my time\u000aA friend of the devil is a friend of mine\u000aIf I get home before daylight I just might get some sleep\u000aTonight\u000a\u000aI ran into the devil babe, he loaned me twenty bills\u000aI spent the night in Utah in a cave up in the hills\u000a\u000aChorus\u000a\u000aI ran down to the levee but the devil caught me there\u000aHe took my twenty dollar bill and vanished in the air\u000a\u000aChorus\u000a\u000aGot two reasons why I cry away each lonely night\u000aThe first one''s named sweet Anne Marie and she''s my heart''s delight\u000aSecond one is prison baby, sheriff''s on my trail\u000aAnd if he catches up with me I''ll spend my life in jail\u000a\u000aGot a wife in Chino babe, and one in Cherokee\u000aFirst one says she''s got my child but it don''t look like me\u000a\u000aChorus'),'Friend of the Devil Score.pdf',2,NULL,NULL,6,3);
INSERT INTO Song VALUES(72,'Bertha','bertha',unistr('I had a hard run\u000aRunning from your window\u000aI was all night running, running\u000aLord, I wonder if you care\u000aI had a run in\u000aRun around and a run down\u000aRun around the corner, corner\u000aLord, I ran smack into a tree\u000a\u000aChorus\u000aI had to move\u000aReally had to move\u000aThat''s why if you please\u000aI am on my bended knees\u000aBertha, don''t you come around here any more\u000a\u000aDressed myself in green\u000aLord I went down unto the sea\u000aTry to see what''s going down\u000aLord, try to read between the lines\u000aI had a feeling I was falling, falling, falling\u000aLord, I turned round to see\u000aHeard a voice a-calling\u000aLord you was coming after me\u000a\u000aChorus\u000a\u000aRan into a rain-storm\u000aDucked into a bar door\u000aIt was all night pouring, pouring rain\u000aLord but not a drop on me\u000aTest me, test me, test me, test me, test me\u000aWhy don''t you arrest me\u000aThrow me in the jail house\u000aLord, until the sun go down\u000a\u000aChorus'),'Bertha Score.pdf',1,NULL,NULL,7,3);
INSERT INTO Song VALUES(73,'Blow Away','blow-away',unistr('A man and a woman come together as strangers\u000aWhen they part they''re usually strangers still\u000aIt''s like a practical joke played on us by our Maker\u000aEmpty bottles that can''t be filled\u000a\u000aChorus\u000aBaby who''s to say it could have been different now that it''s done\u000aBaby who''s to say that it should have been, anyway\u000aBaby who''s to say that it even matters in the long run\u000aGive it just a minute\u000aAnd it will blow away\u000aIt''ll blow away\u000a\u000aYou fancy me to be the master of your feelings\u000aYou barely bruise me with your looks to kill\u000aThough I admit we were sometimes brutal in our dealings\u000aI never held you against your will\u000a\u000aChorus\u000a\u000aYour case against me is so very clearly stated\u000aI plead no contest, I just turn and shrug\u000aI''ve come to figure all importance overestimated\u000aYou must mean water when you beg for blood\u000a\u000aChorus\u000a\u000aLike a feather in a whirlwind\u000aBlow away\u000aJust as sure as the world spins\u000aBlow away\u000a[etc]'),'Blow Away Score.pdf',4,NULL,NULL,18,2);
INSERT INTO Song VALUES(74,'Death Don''t Have No Mercy','death-dont-have-no-mercy',unistr('Y'' Know Death Don''t Have No Mercy In This Land\u000aDeath Don''t Have No Mercy In This Land, In This Land\u000aCome To Your House, You Know He Don''t Take Long\u000aLook In Bed This Morning, Children Find Your Mother Gone.\u000a\u000aI Said Death Don''t Have No Mercy In This Land.\u000aDeath Will Leave You Standing And Crying In This Land,\u000aDeath Will Leave You Standing And Crying In This Land, In This Land, Yeah!\u000a\u000aWhoa! Come To Your House, Y'' Know He Don''t Stay Long,\u000aY'' Look In Bed This Morning,\u000aChildren You Find That Your Brothers And Sisters Are Gone.\u000aI Said Death Don''t Have No Mercy In This Land.\u000a\u000aDeath Will Go In Any Family In This Land.\u000aDeath Will Go In Any Family In This Land.\u000aCome To Your House, you know he don''t take long.\u000aLook in the bed on the morning, Children Find That Your Family''s Gone.\u000a\u000aI Said Death Don''t Have No Mercy In This Land.\u000aDeath Will Leave You Standing And Crying In This Land,\u000aIn This Land. Whoa! Come To Your House,\u000aY'' Know It Don''t Stay Long, Y'' Look In Bed This Morning,\u000aChildren Find That Your Brothers And Sisters Are Gone.\u000a\u000aI Said Death Don''t, Death Don''t Have No Mercy In This Land.'),'Death Don''t Have No Mercy Score.pdf',5,NULL,'cover',4,3);
INSERT INTO Song VALUES(75,'Black-Throated Wind','black-throated-wind',unistr('Bringing me down, I''m running aground\u000aBlind in the light of the interstate cars\u000aPassing me by, the buses and semis\u000aPlunging like stones from a slingshot on Mars\u000a\u000aBut I''m here by the road, bound to the load\u000aThat I picked up in ten thousand cafes and bars\u000aAlone with the rush of the drivers who won''t pick me up\u000aThe highway, the moon, the clouds, and the stars\u000a\u000aThe black throated wind keeps on pouring in\u000aWith its words of a life where nothing is new\u000aAh, Mother American Night, I''m lost from the light\u000aOh I''m drowning in you\u000a\u000aI left Saint Louis, City of Blues\u000aIn the midst of a storm I''d rather forget\u000aI tried to pretend it came to an end\u000a''Cause you weren''t the woman I once thought I''d met\u000a\u000aBut I can''t deny, that times have gone by\u000aWhere I never had doubts or thoughts of regrets\u000aAnd I was a man when all this began\u000aWho wouldn''t think twice about being there yet\u000a\u000aThe black throated wind whispering sin,\u000aAnd it speaks of a life that passes like dew\u000aIt forced me to see\u000aThat you''ve done better by me\u000aBetter by me than I''ve done by you\u000a\u000aNow what''s to found, racing around\u000aYou carry your pain wherever you go\u000aFull of the blues, and trying to lose\u000aYou ain''t going to learn what you don''t want to know\u000a\u000aSo I give you my eyes, and all of their lies\u000aPlease help them to learn as well as to see\u000aAnd capture a glance, whoa and make it a dance\u000aOf looking at you looking at me\u000a\u000aThe black throated wind keeps on pouring in\u000aWith its words of a life that could almost be true\u000aAh, Mother American Night, here comes the light\u000aI''m turning around that''s what I''m going to do\u000aGoing back home that''s what I''m gonna do'),'Black-Throated Wind Score.pdf',2,NULL,NULL,8,1);
INSERT INTO Song VALUES(76,'Feel Like a Stranger','feel-like-a-stranger',unistr('Inside you''re burning\u000aI can see clear through\u000aYour eyes tell more than you mean them to\u000a\u000aLit up and flashing\u000aLike the reds and blues\u000aOut there on the neon avenue\u000a\u000aBut I feel like a stranger\u000aFeel like a stranger\u000a\u000aWell the music''s thundering\u000aWe''re restless and hot\u000aYou keep firing glances across the room\u000a\u000aAnd I can''t stop wondering\u000aJust what you got\u000aGet the feeling I''m gonna find out real soon\u000a\u000aStill I feel like a stranger\u000aFeel like a stranger\u000aWell you know it''s gonna get stranger\u000aSo let''s get on with the show\u000a\u000aYes and the wheel\u000aGets smoking round midnight\u000aYou shoot me a look that said let''s go\u000a\u000aYes and it feels\u000aJust like running a red light\u000aThere ain''t no point in looking behind us, no\u000a\u000aBut I feel like a stranger\u000aFeel like a stranger\u000aYou know it keeps getting stranger and stranger\u000aIf it''s love then how would I know?\u000a\u000aYes and it''s gonna get stranger\u000aSome things you just know\u000a\u000aIf this were love then how would I know\u000a(Feel like a stranger)\u000a(Feel like a stranger)\u000aFeel like a stranger\u000a(Feel like a stranger)\u000aIt''s gonna be a long hot crazy night\u000aIt''s gonna be a long long crazy crazy night\u000aYeah crazy night\u000aSilky silky, crazy crazy night'),'Feel Like a Stranger Score.pdf',4,NULL,NULL,16,1);
INSERT INTO Song VALUES(77,'Eyes of the World','eyes-of-the-world',unistr('Right outside this lazy summer home\u000aYou ain''t got time to call your soul a critic, no\u000aRight outside the lazy gate\u000aOf winter''s summer home\u000aWondering where the nuthatch winters\u000aWings a mile long\u000aJust carried the bird away\u000a\u000aChorus\u000aWake up to find out that you are the eyes of the world\u000aBut the heart has its beaches, its homeland and thoughts of its own\u000aWake now discover that you are the song that the morning brings\u000aBut the heart has its seasons, its evenings and songs of its own\u000a\u000aThere comes a redeemer and he slowly, too, fades away\u000aAnd there follows his wagon behind him that''s loaded with clay\u000aAnd the seeds that were silent all burst into bloom and decay\u000aAnd night comes so quiet, it''s close on the heels of the day\u000a\u000aChorus\u000a\u000aSometimes we live no particular way but our own\u000aAnd sometimes we visit your country and live in your home\u000aSometimes we ride on your horses, sometimes we walk alone\u000aSometimes the songs that we hear are just songs of our own\u000a\u000aChorus'),'Eyes of the World Score.pdf',6,NULL,NULL,11,3);
INSERT INTO Song VALUES(78,'China Doll','china-doll',unistr('A pistol shot at five o''clock\u000aThe bells of heaven ring\u000aTell me what you done it for\u000a"No I won''t tell you a thing\u000a\u000a"Yesterday I begged you\u000aBefore I hit the ground --\u000aAll I leave behind me\u000aIs only what I found\u000a\u000a"If you can abide it\u000aLet the hurdy gurdy play\u000aStranger ones have come by here\u000aBefore they flew away\u000a\u000a"I will not condemn you\u000aNor yet would I deny ..."\u000aI would ask the same of you\u000aBut failing, will not die ...\u000a\u000aTake up your china doll\u000aIt''s only fractured --\u000aJust a little nervous from the fall\u000a\u000aLa la la la la la la'),'China Doll Score.pdf',2,NULL,NULL,12,3);
INSERT INTO Song VALUES(79,'Days Between','days-between',unistr('There were days, and there were days\u000aAnd there were days between\u000aSummer flies and August dies\u000aThe world grows dark and mean\u000aComes the shimmer of the moon\u000aOn black infested trees\u000aThe singing man is at his song\u000aThe holy on their knees\u000aThe reckless are out wrecking\u000aThe timid plead their pleas\u000aNo one knows much more of this\u000aThan anyone can see\u000aAnyone can see\u000a\u000aThere were days, and there were days\u000aAnd there were days besides\u000aWhen phantom ships with phantom sails\u000aSet to sea on phantom tides\u000aComes the lightning of the sun\u000aOn bright unfocused eyes\u000aThe blue of yet another day\u000aA springtime wet with sighs\u000aA hopeful candle lingers\u000aIn the land of lullabies\u000aWhere headless horsemen vanish\u000aWith wild and lonely cries\u000aLonely cries\u000a\u000aThere were days, and there were days\u000aAnd there were days I know\u000aWhen all we ever wanted\u000aWas to learn and love and grow\u000aOnce we grew into our shoes\u000aWe told them where to go\u000aWalked halfway around the world\u000aOn promise of the glow\u000aStood upon a mountain top\u000aWalked barefoot in the snow\u000aGave the best we had to give\u000aHow much we''ll never know\u000aWe''ll never know\u000a\u000aThere were days, and there were days\u000aAnd there were days between\u000aPolished like a golden bowl\u000aThe finest ever seen\u000aHearts of Summer held in trust\u000aStill tender young and green\u000aLeft on shelves collecting dust\u000aNot knowing what they mean\u000aValentines of flesh and blood\u000aAs soft as velveteen\u000aHoping love would not forsake\u000aThe days that lie between\u000aLie between'),'Days Between Score.pdf',NULL,NULL,NULL,19,3);
INSERT INTO Song VALUES(80,'Deal','deal',unistr('Since it cost a lot to win\u000aAnd even more to lose\u000aYou and me bound to spend some time\u000aWondering what to choose\u000a\u000aChorus\u000aGoes to show, you don''t ever know\u000aWatch each card you play and play it slow\u000aWait until that deal come round\u000aDon''t you let that deal go down, no, no\u000a\u000aI''ve been gambling here abouts\u000aFor ten good solid years\u000aIf I told you all that went down\u000aIt would burn off both your ears\u000a\u000aChorus\u000a\u000aSince you poured the wine for me\u000aAnd tightened up my shoes\u000aI hate to leave you sitting there\u000aComposing lonesome blues\u000a\u000aChorus\u000aWait until that deal come round\u000aDon''t you let that deal go down\u000a[repeat etc]'),'Deal Score.pdf',1,NULL,NULL,9,3);
INSERT INTO Song VALUES(81,'Dire Wolf','dire-wolf',unistr('In the timbers of Fennario the wolves are running round\u000aThe winter was so hard and cold, froze ten feet ''neath the ground\u000a\u000aChorus\u000aDon''t murder me, I beg of you don''t murder me\u000aPlease don''t murder me\u000a\u000aI sat down to supper, ''twas a bottle of red whiskey\u000aI said my prayers and went to bed, that''s the last they saw of me\u000aChorus\u000a\u000aWhen I awoke, the dire wolf, six hundred pounds of sin\u000aWas grinning at my window, all I said was "Come on in"\u000aChorus\u000a\u000aThe wolf came in, I got my cards, we sat down for a game\u000aI cut my deck to the queen of spades but the cards were all the same\u000aChorus\u000a\u000aIn the back-wash of Fennario, the black and bloody mire\u000aThe dire wolf collects his due while the boys sing round the fire\u000aChorus'),'Dire Wolf Score.pdf',3,NULL,NULL,5,3);
INSERT INTO Song VALUES(82,'Turn On Your Lovelight','turn-on-your-lovelight',unistr('Without a warning you broke my heart, takin'' it baby, tore it apart\u000aAnd you left me standin'' in the dark, said your love for me was dyin''\u000a\u000aCome on baby, baby please come on baby, cause I''m on my knees\u000aTurn on your lights let it shine on me shine on your love light\u000aLet it shine on me let shine, let it shine\u000a\u000aWhen I get lonely in the middle of the night\u000aAnd I need you darlin'' to make things all right\u000a\u000aSo come on baby, baby please and I''m beggin'' you baby cause I''m on my knees,\u000aTurn on your lights let it shine on me\u000aTurn on your love light let it shine on me\u000aLet it shine, let it shine, let it\u000a\u000aWithout a warning you broke my heart, takin'' it baby, tore it apart\u000aAnd you left me standin'' in the dark, shine your love for me was dark\u000a\u000aCome on baby, baby please come on baby, cause I''m on my knees\u000aTurn on your lights let it shine on me turn on your love light\u000aLet it shine, let shine'),'Turn On Your Lovelight Score.pdf',4,NULL,NULL,4,5);
